INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hypothesis-1', 'hypothesis', 'The researchers designed a simple test to check their hypothesis about bird migration.', '研究者设计了一项简单的测试,来检验他们关于鸟类迁徙的假设。', 'hypothesis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('theory-1', 'theory', 'According to one theory, the stone circle was used to track the seasons.', '有一种理论认为,这个石圈曾被用来追踪季节变化。', 'theory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assumption-1', 'assumption', 'The model rests on the assumption that prices will remain stable.', '这个模型基于一个假定:价格将保持稳定。', 'assumption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('premise-1', 'premise', 'The theory rests on the premise that all languages share a basic structure.', '这一理论有一个前提:所有语言都有相同的基本结构。', 'premise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evidence-1', 'evidence', 'There is little evidence that the new teaching method improves exam results.', '几乎没有证据表明新教学方法能提高考试成绩。', 'evidence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proof-1', 'proof', 'So far, scientists have found no proof of life on other planets.', '到目前为止,科学家还没有找到其他星球存在生命的证明。', 'proof');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('argument-1', 'argument', 'The main argument of the article is that cities need more green space.', '这篇文章的主要论点是城市需要更多绿地。', 'argument');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('argument-2', 'argument', 'The plan led to a long argument among members of the committee.', '这项计划在委员会成员中引发了长时间的争论。', 'argument');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('claim-1', 'claim', 'The company''s claim that its product saves energy has been questioned.', '该公司声称产品节能,这一说法受到了质疑。', 'claim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('claim-2', 'claim', 'Some historians claim that the tower was built much earlier than records show.', '一些历史学家声称,这座塔的建造时间比记载的要早得多。', 'claim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assert-1', 'assert', 'The author asserts that early education shapes a child''s later success.', '作者断言,早期教育影响孩子日后的成功。', 'asserts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contend-1', 'contend', 'Some economists contend that higher taxes would slow the growth of small businesses.', '一些经济学家主张,提高税收会减缓小企业的发展。', 'contend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contend-2', 'contend', 'Young trees must contend with larger plants for light and water.', '小树必须与较大的植物争夺阳光和水分。', 'contend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maintain-1', 'maintain', 'Critics maintain that the study was too small to be reliable.', '批评者坚持认为,这项研究规模太小,不可靠。', 'maintain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maintain-2', 'maintain', 'Sleep helps the brain to maintain its ability to store new information.', '睡眠有助于大脑维持储存新信息的能力。', 'maintain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('propose-1', 'propose', 'The author proposes a new way of measuring happiness across different countries.', '作者提出了一种衡量不同国家幸福感的新方法。', 'proposes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suggest-1', 'suggest', 'Recent findings suggest that bees can recognise individual human faces.', '最新发现表明,蜜蜂能够识别人类的面孔。', 'suggest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suggest-2', 'suggest', 'The report suggests building more cycle paths to reduce traffic in the city.', '报告建议修建更多自行车道,以减少城市交通流量。', 'suggests');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imply-1', 'imply', 'The results imply that diet may play a larger role than exercise.', '结果暗示,饮食的作用可能比运动更大。', 'imply');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infer-1', 'infer', 'From the tools they left behind, we can infer how these people lived.', '从他们留下的工具中,我们可以推断出这些人的生活方式。', 'infer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deduce-1', 'deduce', 'Scientists can deduce the age of a tree by counting its rings.', '科学家可以通过数年轮推算出树的年龄。', 'deduce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conclude-1', 'conclude', 'The authors conclude that noise has a clear effect on concentration.', '作者得出结论:噪音对注意力有明显影响。', 'conclude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('verify-1', 'verify', 'Other laboratories must verify these results before they can be accepted.', '这些结果必须经其他实验室核实后才能被接受。', 'verify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('validate-1', 'validate', 'Further studies are needed to validate the findings of this small experiment.', '需要进一步研究来证实这个小型实验的结果。', 'validate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refute-1', 'refute', 'New data from the deep ocean appears to refute the earlier theory.', '来自深海的新数据似乎驳斥了早先的理论。', 'refute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dispute-1', 'dispute', 'There is an ongoing dispute among scholars over who wrote the text.', '学者们对这篇文本的作者一直存在争论。', 'dispute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dispute-2', 'dispute', 'Few experts now dispute the link between smoking and heart disease.', '现在很少有专家质疑吸烟与心脏病之间的联系。', 'dispute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('challenge-1', 'challenge', 'These discoveries challenge the traditional view of how farming began.', '这些发现质疑了关于农业起源的传统观点。', 'challenge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('challenge-2', 'challenge', 'Feeding a growing population is a major challenge for many developing countries.', '养活不断增长的人口是许多发展中国家面临的重大挑战。', 'challenge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contradict-1', 'contradict', 'The second survey seems to contradict the results of the first one.', '第二次调查似乎与第一次的结果相矛盾。', 'contradict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('controversial-1', 'controversial', 'The use of animals in medical research remains a controversial issue.', '在医学研究中使用动物仍然是一个有争议的问题。', 'controversial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consensus-1', 'consensus', 'There is now a broad consensus among scientists that the climate is warming.', '现在科学家普遍达成共识:气候正在变暖。', 'consensus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perspective-1', 'perspective', 'The book looks at the Industrial Revolution from the perspective of ordinary workers.', '这本书从普通工人的视角审视工业革命。', 'perspective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notion-1', 'notion', 'The notion that intelligence is fixed at birth is no longer widely accepted.', '智力天生固定这一观念已不再被广泛接受。', 'notion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concept-1', 'concept', 'The concept of time differs greatly from one culture to another.', '时间的概念在不同文化之间差异很大。', 'concept');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('framework-1', 'framework', 'The study provides a useful framework for understanding how children learn languages.', '这项研究为理解儿童如何学习语言提供了一个有用的框架。', 'framework');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paradigm-1', 'paradigm', 'The discovery led to a paradigm shift in the way scientists viewed disease.', '这一发现使科学家看待疾病的范式发生了转变。', 'paradigm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('principle-1', 'principle', 'The experiment is based on a simple principle of physics.', '这个实验基于一条简单的物理学原理。', 'principle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('principle-2', 'principle', 'Fairness is a basic principle of any good legal system.', '公平是任何良好法律体系的基本原则。', 'principle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('criterion-1', 'criterion', 'Cost should not be the only criterion for choosing a treatment.', '成本不应是选择治疗方案的唯一标准。', 'criterion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parameter-1', 'parameter', 'The computer model allows researchers to change each parameter in turn.', '这个计算机模型让研究者可以依次改变每个参数。', 'parameter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('variable-1', 'variable', 'Age was the most important variable in predicting how people responded.', '年龄是预测人们反应的最重要变量。', 'variable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('variable-2', 'variable', 'Rainfall in this region is highly variable from one year to the next.', '该地区的降雨量每年变化很大。', 'variable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('factor-1', 'factor', 'Income is an important factor in deciding where families choose to live.', '收入是决定家庭选择居住地的重要因素。', 'factor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('element-1', 'element', 'Trust is a key element of any successful business relationship.', '信任是任何成功商业关系的关键要素。', 'element');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('element-2', 'element', 'Hydrogen is the lightest element and the most common in the universe.', '氢是最轻的元素,也是宇宙中最常见的元素。', 'element');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('component-1', 'component', 'Sleep is an essential component of a healthy lifestyle.', '睡眠是健康生活方式的重要组成部分。', 'component');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aspect-1', 'aspect', 'The study focuses on one aspect of memory that is often overlooked.', '这项研究聚焦于记忆中常被忽视的一个方面。', 'aspect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dimension-1', 'dimension', 'Music adds an emotional dimension that a written text cannot provide.', '音乐增添了文字无法提供的情感维度。', 'dimension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scope-1', 'scope', 'The scope of the study was limited to schools in rural areas.', '这项研究的范围仅限于农村地区的学校。', 'scope');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('context-1', 'context', 'Words can have very different meanings depending on the context.', '根据语境不同,词语的含义可能大不相同。', 'context');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phenomenon-1', 'phenomenon', 'Scientists still cannot fully explain this unusual weather phenomenon.', '科学家仍然无法完全解释这种不寻常的天气现象。', 'phenomenon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mechanism-1', 'mechanism', 'Sweating is the body''s main mechanism for controlling its temperature.', '出汗是人体调节体温的主要机制。', 'mechanism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('process-1', 'process', 'Learning a language is a slow process that requires regular practice.', '学习语言是一个缓慢的过程,需要经常练习。', 'process');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('process-2', 'process', 'The brain can process images far more quickly than written words.', '大脑处理图像的速度远远快于处理文字。', 'process');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('procedure-1', 'procedure', 'The researchers followed the same procedure for every participant in the study.', '研究者对每位参与者都采用了相同的程序。', 'procedure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('approach-1', 'approach', 'This approach to teaching encourages students to solve problems on their own.', '这种教学方法鼓励学生自己解决问题。', 'approach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('approach-2', 'approach', 'As birds approach the end of their journey, they begin to fly lower.', '鸟类接近旅程终点时,会开始飞得更低。', 'approach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strategy-1', 'strategy', 'Hiding in tall grass is a common survival strategy among young deer.', '躲在高草丛中是幼鹿常见的生存策略。', 'strategy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('technique-1', 'technique', 'Farmers developed a new technique for storing water during the dry season.', '农民发展出一种在旱季储水的新技术。', 'technique');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('method-1', 'method', 'This method of dating ancient objects is accurate but very expensive.', '这种测定古物年代的方法准确但非常昂贵。', 'method');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('investigate-1', 'investigate', 'The team set out to investigate why the fish had disappeared from the lake.', '研究团队着手调查湖中的鱼为什么消失了。', 'investigate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('examine-1', 'examine', 'This chapter will examine the causes of the economic crisis.', '本章将审视这场经济危机的成因。', 'examine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('explore-1', 'explore', 'Researchers are now exploring ways of turning waste into fuel.', '研究者正在探索把废弃物转化为燃料的方法。', 'exploring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('analyse-1', 'analyse', 'Scientists analysed samples of ice to learn about the climate of the past.', '科学家分析了冰样,以了解过去的气候。', 'analysed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assess-1', 'assess', 'It is difficult to assess the long-term effects of the new policy.', '很难评估这项新政策的长期影响。', 'assess');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evaluate-1', 'evaluate', 'The study set out to evaluate three different methods of teaching reading.', '这项研究旨在评价三种不同的阅读教学方法。', 'evaluate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('measure-1', 'measure', 'The device can measure small changes in the temperature of the water.', '这种设备能测量水温的微小变化。', 'measure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('measure-2', 'measure', 'The government has introduced measures to reduce air pollution in large cities.', '政府已出台措施,减少大城市的空气污染。', 'measures');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quantify-1', 'quantify', 'It is hard to quantify the benefits of spending time in nature.', '亲近自然的益处很难量化。', 'quantify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('identify-1', 'identify', 'The test helps doctors to identify the disease at an early stage.', '这项检测帮助医生在早期发现这种疾病。', 'identify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('classify-1', 'classify', 'Biologists classify animals according to their shared physical features.', '生物学家根据共同的身体特征对动物进行分类。', 'classify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('categorise-1', 'categorise', 'The researchers categorised the responses as either positive or negative.', '研究者把这些回答归为正面或负面两类。', 'categorised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('define-1', 'define', 'It is surprisingly difficult to define exactly what intelligence means.', '要准确定义智力的含义,出乎意料地困难。', 'define');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interpret-1', 'interpret', 'Historians interpret the meaning of these ancient paintings in different ways.', '历史学家对这些古代绘画的含义有不同的解读。', 'interpret');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illustrate-1', 'illustrate', 'The story of the island illustrates how quickly a species can disappear.', '这座岛的故事说明了一个物种消失得有多快。', 'illustrates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('demonstrate-1', 'demonstrate', 'The experiment demonstrated that plants can respond to sound.', '这项实验证明了植物能够对声音作出反应。', 'demonstrated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indicate-1', 'indicate', 'These figures indicate that fewer young people are moving to rural areas.', '这些数字表明,搬到农村的年轻人减少了。', 'indicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reveal-1', 'reveal', 'Satellite images revealed a network of ancient roads beneath the forest.', '卫星图像揭示了森林下面的古代道路网。', 'revealed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('highlight-1', 'highlight', 'The report highlights the need for more investment in public transport.', '这份报告强调了增加公共交通投资的必要性。', 'highlights');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('highlight-2', 'highlight', 'The highlight of the exhibition is a collection of early maps.', '这次展览最精彩的部分是一批早期地图。', 'highlight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emphasise-1', 'emphasise', 'The author emphasises the importance of sleep for memory.', '作者强调了睡眠对记忆的重要性。', 'emphasises');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('underline-1', 'underline', 'The latest figures underline the seriousness of the water shortage.', '最新数据凸显了水资源短缺的严重性。', 'underline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cite-1', 'cite', 'Many studies cite this early work as the starting point of the field.', '许多研究引用这项早期成果,把它视为该领域的起点。', 'cite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quote-1', 'quote', 'The article quotes a scientist who worked on the original project.', '这篇文章引用了一位参与原项目的科学家的话。', 'quotes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refer-to-1', 'refer-to', 'The term ''biodiversity'' is used to refer to the variety of life on Earth.', '“生物多样性”一词指的是地球上生命的多样性。', 'refer to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attribute-1', 'attribute', 'Some experts attribute the fall in crime to better street lighting.', '一些专家把犯罪率下降归因于街道照明的改善。', 'attribute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attribute-2', 'attribute', 'Patience is an important attribute for anyone working with young children.', '耐心是与幼儿打交道的人应具备的重要特质。', 'attribute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correlate-1', 'correlate', 'Levels of education tend to correlate with income in later life.', '教育水平往往与日后的收入相关联。', 'correlate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correlation-1', 'correlation', 'The study found a strong correlation between exercise and improved mood.', '研究发现,锻炼与情绪改善之间有很强的相关性。', 'correlation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('replicate-1', 'replicate', 'Other researchers were unable to replicate the results of the original study.', '其他研究者未能重现最初那项研究的结果。', 'replicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('simulate-1', 'simulate', 'Computers can simulate how a building would behave in an earthquake.', '计算机可以模拟建筑物在地震中的表现。', 'simulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('predict-1', 'predict', 'It is still impossible to predict exactly when an earthquake will occur.', '目前仍然无法准确预测地震发生的时间。', 'predict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forecast-1', 'forecast', 'Long-range forecasts of the weather are often less accurate than short ones.', '长期天气预报的准确度往往低于短期预报。', 'forecasts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forecast-2', 'forecast', 'Experts forecast that demand for clean energy will continue to rise.', '专家预测,对清洁能源的需求将持续上升。', 'forecast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('estimate-1', 'estimate', 'Current estimates put the number of species in the forest at over ten thousand.', '目前估计,这片森林中的物种超过一万种。', 'estimates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('estimate-2', 'estimate', 'Researchers estimate that the cave was first used around ten thousand years ago.', '研究者估计,这个洞穴大约一万年前开始被使用。', 'estimate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('approximate-1', 'approximate', 'The map shows the approximate location of the ancient settlement.', '地图标出了这处古代聚落的大致位置。', 'approximate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('precise-1', 'precise', 'Modern clocks allow scientists to make extremely precise measurements of time.', '现代时钟让科学家能够极其精确地测量时间。', 'precise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accurate-1', 'accurate', 'The instrument gives a more accurate reading than older equipment.', '这种仪器的读数比旧设备更准确。', 'accurate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reliable-1', 'reliable', 'Self-reported data on diet is not always reliable, as people forget details.', '人们自述的饮食数据并不总是可靠,因为他们会忘记细节。', 'reliable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('valid-1', 'valid', 'The results are only valid if the sample represents the whole population.', '只有样本能代表总体,结果才有效。', 'valid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('empirical-1', 'empirical', 'There is little empirical evidence to support this popular belief.', '几乎没有实证证据支持这种流行的看法。', 'empirical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('theoretical-1', 'theoretical', 'The idea remains theoretical, as no one has yet tested it in practice.', '这个想法仍停留在理论层面,因为还没有人在实践中验证过。', 'theoretical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('systematic-1', 'systematic', 'The team carried out a systematic review of all the earlier studies.', '研究团队对此前所有研究进行了系统性回顾。', 'systematic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rigorous-1', 'rigorous', 'All new medicines must pass rigorous tests before they can be sold.', '所有新药上市前都必须通过严格的测试。', 'rigorous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subjective-1', 'subjective', 'Judgements about the quality of art are inevitably subjective.', '对艺术品质量的判断难免是主观的。', 'subjective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bias-1', 'bias', 'Researchers must be careful to avoid bias when they select participants.', '研究者在挑选参与者时必须小心避免偏差。', 'bias');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anomaly-1', 'anomaly', 'One unusually warm year may be an anomaly rather than part of a trend.', '某一年异常温暖可能只是个例外情况,而不代表某种趋势。', 'anomaly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exception-1', 'exception', 'Most birds build nests, but there are some notable exceptions to this rule.', '大多数鸟都筑巢,但也有一些明显的例外。', 'exceptions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('limitation-1', 'limitation', 'One limitation of the study is that all the participants were university students.', '这项研究的一个局限是所有参与者都是大学生。', 'limitation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flaw-1', 'flaw', 'A serious flaw in the design caused the bridge to shake in strong winds.', '设计上的严重缺陷导致这座桥在强风中摇晃。', 'flaw');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drawback-1', 'drawback', 'The main drawback of solar power is that it depends on the weather.', '太阳能的主要缺点是依赖天气。', 'drawback');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('merit-1', 'merit', 'Each of these approaches has its own merit, depending on the situation.', '根据情况不同,这些方法各有优点。', 'merit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('implication-1', 'implication', 'The findings have important implications for how we treat young patients.', '这些发现对我们如何治疗年轻患者有重要影响。', 'implications');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('significance-1', 'significance', 'Few people understood the significance of the discovery at the time.', '当时很少有人理解这一发现的重要性。', 'significance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relevance-1', 'relevance', 'Critics have questioned the relevance of these old laws to modern life.', '批评者质疑这些旧法律与现代生活的相关性。', 'relevance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insight-1', 'insight', 'The letters give us a valuable insight into daily life in the eighteenth century.', '这些信件让我们得以深入了解十八世纪的日常生活。', 'insight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scrutiny-1', 'scrutiny', 'The company''s safety record has come under close scrutiny since the accident.', '事故发生后,该公司的安全记录受到了严格审查。', 'scrutiny');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inference-1', 'inference', 'The researchers drew an inference about diet from the marks on the teeth.', '研究者根据牙齿上的痕迹对饮食作出了推断。', 'inference');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('induction-1', 'induction', 'Induction involves forming a general rule from a number of specific examples.', '归纳是指从若干具体例子中得出一般规律。', 'Induction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('induction-2', 'induction', 'All new employees attend a one-week induction before starting work.', '所有新员工在开始工作前都要参加为期一周的入职培训。', 'induction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deduction-1', 'deduction', 'By careful deduction, the scientist worked out where the signal came from.', '通过仔细推论,这位科学家确定了信号的来源。', 'deduction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('homogeneous-1', 'homogeneous', 'The sample was fairly homogeneous, with most participants coming from one city.', '样本相当同质,大多数参与者来自同一座城市。', 'homogeneous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discrete-1', 'discrete', 'The process can be divided into four discrete stages.', '这个过程可以分为四个独立的阶段。', 'discrete');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('variant-1', 'variant', 'A new variant of the virus spread rapidly across the region.', '这种病毒的一种新变体在该地区迅速传播。', 'variant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('existence-1', 'existence', 'The existence of water on Mars was confirmed by a recent mission.', '最近的一次探测任务证实了火星上存在水。', 'existence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('logical-1', 'logical', 'Reducing car use seems a logical step towards cleaner air.', '减少用车似乎是改善空气质量的合理一步。', 'logical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clue-1', 'clue', 'The shape of the bones provides a clue to how the animal moved.', '骨骼的形状为了解这种动物的运动方式提供了线索。', 'clue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stance-1', 'stance', 'Scientists have taken a more cautious stance on the use of the new drug.', '科学家对使用这种新药采取了更谨慎的立场。', 'stance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preliminary-1', 'preliminary', 'Preliminary results suggest that the treatment may be effective in most patients.', '初步结果表明,这种疗法可能对大多数患者有效。', 'Preliminary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accuracy-1', 'accuracy', 'The accuracy of weather forecasts has improved greatly over the last thirty years.', '过去三十年,天气预报的准确性大大提高。', 'accuracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reliability-1', 'reliability', 'Doubts have been raised about the reliability of data collected by telephone.', '电话收集的数据的可靠性受到了质疑。', 'reliability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('presume-1', 'presume', 'Without written records, we can only presume that the building had a religious purpose.', '由于没有文字记录,我们只能推测这座建筑有宗教用途。', 'presume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('critique-1', 'critique', 'Her latest book offers a sharp critique of modern consumer society.', '她的新书对现代消费社会提出了尖锐的评论。', 'critique');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('analogy-1', 'analogy', 'The author uses the analogy of a computer to explain how memory works.', '作者用计算机作类比来解释记忆的运作方式。', 'analogy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gauge-1', 'gauge', 'Surveys are used to gauge public opinion on major social issues.', '调查被用来判断公众对重大社会问题的看法。', 'gauge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plausible-1', 'plausible', 'It seems plausible that climate change forced these people to move south.', '气候变化迫使这些人南迁,这种说法似乎有道理。', 'plausible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('randomly-1', 'randomly', 'Patients were randomly assigned to one of the two treatment groups.', '患者被随机分配到两个治疗组之一。', 'randomly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('randomise-1', 'randomise', 'Researchers randomise the order of questions to prevent any pattern affecting the answers.', '研究者把问题的顺序随机化,以防某种规律影响答案。', 'randomise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('qualitative-1', 'qualitative', 'The team collected qualitative data through long interviews with local farmers.', '研究团队通过与当地农民的长时间访谈收集了定性数据。', 'qualitative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('variability-1', 'variability', 'The study found great variability in the way that children develop speech.', '研究发现,儿童语言发展的方式差异很大。', 'variability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confound-1', 'confound', 'Differences in diet could confound the results of the exercise study.', '饮食差异可能混淆这项运动研究的结果。', 'confound');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('null-1', 'null', 'The null hypothesis states that the two groups show no real difference.', '零假设认为这两组之间没有真正的差异。', 'null');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('logic-1', 'logic', 'The logic of the argument is clear, but its conclusion is hard to accept.', '这个论点的逻辑很清楚,但结论很难接受。', 'logic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('certainty-1', 'certainty', 'We cannot say with certainty when the first humans reached the island.', '我们无法确切地说出最早的人类何时到达这座岛。', 'certainty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('precedent-1', 'precedent', 'The court''s decision set an important precedent for future cases.', '法院的这项裁决为今后的案件树立了重要先例。', 'precedent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scenario-1', 'scenario', 'In the worst scenario, sea levels could rise by more than one metre.', '在最坏的情景下,海平面可能上升超过一米。', 'scenario');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lifetime-1', 'lifetime', 'An average person will spend about a third of their lifetime asleep.', '普通人一生中大约有三分之一的时间在睡觉。', 'lifetime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('closure-1', 'closure', 'The closure of the mine left hundreds of local people without work.', '矿山关闭导致数百名当地人失业。', 'closure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('domain-1', 'domain', 'Until recently, this area of research was the domain of a few specialists.', '直到最近,这一研究领域还只属于少数专家。', 'domain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('necessity-1', 'necessity', 'The drought made careful use of water an absolute necessity for farmers.', '干旱使节约用水成为农民的绝对必要之事。', 'necessity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('essence-1', 'essence', 'The essence of the theory can be explained in just a few words.', '这个理论的精髓用几句话就能解释清楚。', 'essence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('array-1', 'array', 'The rainforest contains a remarkable array of plants and animals.', '雨林中有种类惊人的动植物。', 'array');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hierarchy-1', 'hierarchy', 'Wolves live in groups with a strict social hierarchy.', '狼生活在群体中,有严格的社会等级制度。', 'hierarchy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flexibility-1', 'flexibility', 'Working from home gives employees greater flexibility in organising their time.', '在家办公让员工在安排时间上更加灵活。', 'flexibility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('duration-1', 'duration', 'The duration of the treatment depends on how serious the illness is.', '治疗的持续时间取决于病情的严重程度。', 'duration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('availability-1', 'availability', 'The availability of cheap food has changed the way people eat.', '廉价食品容易买到,这改变了人们的饮食方式。', 'availability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('realm-1', 'realm', 'Such ideas were once considered to belong to the realm of science fiction.', '这样的想法曾被认为属于科幻小说的领域。', 'realm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breakdown-1', 'breakdown', 'A breakdown in communication between the two teams caused the project to fail.', '两个团队之间的沟通崩溃导致项目失败。', 'breakdown');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breakdown-2', 'breakdown', 'The table gives a breakdown of the costs by country.', '这张表按国家列出了费用细目。', 'breakdown');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dilemma-1', 'dilemma', 'Doctors face a dilemma when a treatment could both help and harm a patient.', '当一种疗法对患者既有益又有害时,医生就面临两难。', 'dilemma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rejection-1', 'rejection', 'The rejection of the proposal surprised many members of the committee.', '提案被否决令委员会的许多成员感到意外。', 'rejection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defect-1', 'defect', 'A small defect in the lens made the early telescope less useful.', '镜片的一个小缺陷使这台早期望远镜不太好用。', 'defect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chunk-1', 'chunk', 'Language learners often remember useful phrases as a single chunk.', '语言学习者常把有用的短语作为一个语块来记忆。', 'chunk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('likelihood-1', 'likelihood', 'Regular exercise reduces the likelihood of developing heart disease.', '经常锻炼可以降低患心脏病的可能性。', 'likelihood');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('continuity-1', 'continuity', 'Older buildings give a town a sense of continuity with its past.', '老建筑让一座城镇与过去之间有一种延续感。', 'continuity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fringe-1', 'fringe', 'The new settlements grew up on the fringe of the desert.', '新的定居点出现在沙漠的边缘。', 'fringe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('threshold-1', 'threshold', 'Sounds above a certain threshold can cause permanent damage to hearing.', '超过一定阈值的声音会对听力造成永久损伤。', 'threshold');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('span-1', 'span', 'The study covers a span of more than fifty years.', '这项研究的时间跨度超过五十年。', 'span');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('span-2', 'span', 'The bird''s migration routes span several continents and thousands of kilometres.', '这种鸟的迁徙路线横跨几个大洲,长达数千公里。', 'span');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manipulation-1', 'manipulation', 'The photographs showed clear signs of manipulation by computer.', '这些照片有明显的计算机操纵痕迹。', 'manipulation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coordination-1', 'coordination', 'Playing a musical instrument requires good coordination between the hands and eyes.', '演奏乐器需要手眼之间良好的协调。', 'coordination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pathway-1', 'pathway', 'Scientists have identified the pathway by which the virus enters the cell.', '科学家已经确定了病毒进入细胞的途径。', 'pathway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('progression-1', 'progression', 'Regular exercise may slow the progression of the disease in older patients.', '经常锻炼可能减缓老年患者的病情发展。', 'progression');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instability-1', 'instability', 'Political instability in the region has discouraged foreign investment.', '该地区的政治不稳定阻碍了外国投资。', 'instability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('displacement-1', 'displacement', 'The building of the dam led to the displacement of thousands of villagers.', '大坝的修建导致数千名村民流离失所。', 'displacement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('facet-1', 'facet', 'Language is only one facet of a people''s cultural identity.', '语言只是一个民族文化身份的一个方面。', 'facet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('selection-1', 'selection', 'The selection of participants was based on age and level of education.', '参与者的选拔依据的是年龄和受教育程度。', 'selection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('theme-1', 'theme', 'Loss and memory are the central themes of the novel.', '失去和记忆是这部小说的中心主题。', 'themes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resolution-1', 'resolution', 'The two countries are still seeking a peaceful resolution to the conflict.', '两国仍在寻求和平解决这场冲突。', 'resolution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resolution-2', 'resolution', 'The new telescope produces images of much higher resolution than before.', '新望远镜拍出的图像分辨率比以前高得多。', 'resolution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boundary-1', 'boundary', 'The river forms a natural boundary between the two regions.', '这条河构成了两个地区之间的天然边界。', 'boundary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assistance-1', 'assistance', 'Many of the poorest farmers rely on assistance from the government.', '许多最贫困的农民依靠政府的帮助。', 'assistance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('agenda-1', 'agenda', 'Climate change is now high on the political agenda in many countries.', '气候变化现在在许多国家的政治议程上占据重要位置。', 'agenda');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transition-1', 'transition', 'The country is going through a slow transition from coal to renewable energy.', '这个国家正在经历从煤炭到可再生能源的缓慢转变。', 'transition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('approval-1', 'approval', 'The new drug has not yet received approval from the health authorities.', '这种新药尚未获得卫生部门的批准。', 'approval');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reputation-1', 'reputation', 'The university has an excellent reputation for research in engineering.', '这所大学在工程研究方面享有极高的声誉。', 'reputation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tendency-1', 'tendency', 'People have a natural tendency to remember bad news better than good news.', '人们天生倾向于比好消息更容易记住坏消息。', 'tendency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('awareness-1', 'awareness', 'Awareness of the dangers of too much sugar has grown in recent years.', '近年来,人们对过量摄入糖分危害的意识有所增强。', 'Awareness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('possession-1', 'possession', 'Possession of land was the main source of power in medieval society.', '在中世纪社会,拥有土地是权力的主要来源。', 'Possession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expansion-1', 'expansion', 'The rapid expansion of cities has put pressure on water supplies.', '城市的快速扩张给供水带来了压力。', 'expansion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pace-1', 'pace', 'The pace of technological change has increased dramatically since the 1990s.', '自 20 世纪 90 年代以来,技术变革的速度急剧加快。', 'pace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guidance-1', 'guidance', 'Young teachers need clear guidance during their first year in the classroom.', '年轻教师在教学的第一年需要明确的指导。', 'guidance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barrier-1', 'barrier', 'Language can be a serious barrier to finding work in a new country.', '在新的国家,语言可能成为求职的严重障碍。', 'barrier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preference-1', 'preference', 'Babies show a clear preference for faces over other objects.', '婴儿明显更喜欢看人脸,而不是其他物体。', 'preference');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ownership-1', 'ownership', 'Car ownership has fallen among young people in many large cities.', '在许多大城市,年轻人的汽车拥有率有所下降。', 'ownership');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enthusiasm-1', 'enthusiasm', 'The public showed little enthusiasm for the government''s new energy plan.', '公众对政府新的能源计划缺乏热情。', 'enthusiasm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('satisfaction-1', 'satisfaction', 'Studies show that job satisfaction depends more on respect than on pay.', '研究表明,工作满意度更多取决于尊重,而不是薪水。', 'satisfaction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confusion-1', 'confusion', 'The similar names of the two species have caused much confusion among scientists.', '这两个物种名称相似,在科学家中引起了很多混乱。', 'confusion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guideline-1', 'guideline', 'The new guidelines advise adults to walk for at least thirty minutes a day.', '新准则建议成年人每天至少步行三十分钟。', 'guidelines');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ease-1', 'ease', 'Thanks to the internet, information can now be shared with ease.', '有了互联网,现在分享信息变得轻而易举。', 'ease');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ease-2', 'ease', 'Green spaces can ease stress and improve the mental health of city residents.', '绿地可以缓解压力,改善城市居民的心理健康。', 'ease');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('declaration-1', 'declaration', 'The declaration of independence marked the beginning of a new nation.', '独立宣言标志着一个新国家的诞生。', 'declaration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('removal-1', 'removal', 'The removal of trees from the hillside increased the risk of flooding.', '山坡上的树木被清除后,洪水风险增加了。', 'removal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('succession-1', 'succession', 'The region suffered a succession of poor harvests during the 1840s.', '19 世纪 40 年代,该地区接连遭遇歉收。', 'succession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('succession-2', 'succession', 'The king''s death led to a long dispute over the succession.', '国王去世后,围绕继承权发生了长期争端。', 'succession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compromise-1', 'compromise', 'The final plan was a compromise between the two opposing groups.', '最终方案是两个对立群体之间的妥协。', 'compromise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compromise-2', 'compromise', 'Neither side was willing to compromise on the question of water rights.', '在水权问题上,双方都不愿意妥协。', 'compromise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chaos-1', 'chaos', 'The sudden flood brought chaos to the transport system of the city.', '突如其来的洪水使城市交通系统陷入混乱。', 'chaos');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intent-1', 'intent', 'The original intent of the law was to protect small farmers.', '这项法律的初衷是保护小农户。', 'intent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sacrifice-1', 'sacrifice', 'Early settlers made great sacrifices to build a new life on the frontier.', '早期定居者为在边疆建立新生活作出了巨大牺牲。', 'sacrifices');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revelation-1', 'revelation', 'The revelation that the data had been changed damaged the scientist''s career.', '数据被篡改一事曝光后,这位科学家的事业受到了损害。', 'revelation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dignity-1', 'dignity', 'Good care allows elderly patients to live with dignity and independence.', '良好的护理让老年患者能够有尊严、独立地生活。', 'dignity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('predecessor-1', 'predecessor', 'The new model uses far less fuel than its predecessor.', '新型号比它的前身省油得多。', 'predecessor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frontier-1', 'frontier', 'Deep-sea exploration is one of the last frontiers of science.', '深海探索是科学最后的前沿之一。', 'frontiers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compliance-1', 'compliance', 'Inspectors visit factories regularly to check compliance with safety rules.', '检查员定期走访工厂,检查是否遵守安全规定。', 'compliance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('denial-1', 'denial', 'The company''s denial of any wrongdoing was not accepted by the court.', '该公司否认有任何不当行为,但法院不予采信。', 'denial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contempt-1', 'contempt', 'Early critics treated the painter''s new style with open contempt.', '早期的评论家公开蔑视这位画家的新风格。', 'contempt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inability-1', 'inability', 'An inability to sleep can seriously affect memory and concentration.', '无法入睡会严重影响记忆力和注意力。', 'inability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disagreement-1', 'disagreement', 'There is still some disagreement about how the ancient city was destroyed.', '关于这座古城如何被毁,目前仍存在一些分歧。', 'disagreement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solidarity-1', 'solidarity', 'The strike was a rare show of solidarity among workers in different industries.', '这次罢工罕见地展现了不同行业工人之间的团结。', 'solidarity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clearance-1', 'clearance', 'Large-scale forest clearance has destroyed the habitat of many animals.', '大规模森林砍伐破坏了许多动物的栖息地。', 'clearance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clearance-2', 'clearance', 'Staff need security clearance to enter this part of the laboratory.', '工作人员需要安全许可才能进入实验室的这一区域。', 'clearance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outset-1', 'outset', 'It was clear from the outset that the project would be expensive.', '从一开始就很清楚,这个项目花费会很高。', 'outset');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('precaution-1', 'precaution', 'Hospitals take every precaution to prevent infections from spreading between patients.', '医院采取一切预防措施,防止感染在病人之间传播。', 'precaution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disposition-1', 'disposition', 'Children with a calm disposition tend to adapt more easily to new schools.', '性情平和的孩子往往更容易适应新学校。', 'disposition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gratitude-1', 'gratitude', 'Studies suggest that expressing gratitude can improve people''s sense of well-being.', '研究表明,表达感激可以提升人们的幸福感。', 'gratitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('allegiance-1', 'allegiance', 'Local rulers were forced to swear allegiance to the new king.', '地方统治者被迫宣誓效忠新国王。', 'allegiance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proximity-1', 'proximity', 'Many early towns grew up because of their proximity to rivers.', '许多早期城镇因靠近河流而发展起来。', 'proximity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inclination-1', 'inclination', 'Few young people have the time or the inclination to learn these old crafts.', '很少有年轻人有时间或意愿学习这些传统手艺。', 'inclination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plight-1', 'plight', 'The article drew attention to the plight of workers in the textile industry.', '这篇文章使人们开始关注纺织业工人的困境。', 'plight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('setback-1', 'setback', 'The failure of the rocket was a major setback for the space programme.', '火箭发射失败是太空计划的一次重大挫折。', 'setback');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impetus-1', 'impetus', 'The oil crisis gave new impetus to research on solar energy.', '石油危机为太阳能研究提供了新的推动力。', 'impetus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contingency-1', 'contingency', 'Governments need a contingency plan in case the water supply fails.', '政府需要制定应急预案,以防供水中断。', 'contingency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('myriad-1', 'myriad', 'The coral reef is home to a myriad of colourful fish.', '珊瑚礁是无数色彩斑斓的鱼类的家园。', 'myriad');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('myriad-2', 'myriad', 'The internet offers myriad ways of learning a new language.', '互联网提供了无数种学习新语言的方法。', 'myriad');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conjunction-1', 'conjunction', 'The drug works best when used in conjunction with regular exercise.', '这种药与规律运动结合使用时效果最好。', 'conjunction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vicinity-1', 'vicinity', 'Several ancient tombs have been found in the vicinity of the village.', '在这个村庄附近发现了几座古墓。', 'vicinity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peril-1', 'peril', 'Sailors of that period faced great peril on every long voyage.', '那个时期的水手每次远航都面临巨大的危险。', 'peril');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ordeal-1', 'ordeal', 'The explorers described their long journey across the ice as a terrible ordeal.', '探险家们把穿越冰原的漫长旅程形容为一场可怕的磨难。', 'ordeal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brink-1', 'brink', 'Hunting had pushed the species to the brink of extinction by 1900.', '到 1900 年,狩猎已把这一物种逼到了灭绝的边缘。', 'brink');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('purity-1', 'purity', 'The purity of the water is tested every day at the treatment plant.', '水处理厂每天检测水的纯净度。', 'purity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cause-1', 'cause', 'Scientists are still trying to find the main cause of the disease.', '科学家仍在努力寻找这种疾病的主要原因。', 'cause');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cause-2', 'cause', 'Heavy rain can cause serious damage to crops in low-lying areas.', '暴雨可能给低洼地区的庄稼造成严重损害。', 'cause');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consequence-1', 'consequence', 'The loss of forests has had serious consequences for local wildlife.', '森林消失给当地野生动物带来了严重后果。', 'consequences');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outcome-1', 'outcome', 'The outcome of the experiment surprised even the researchers themselves.', '实验结果甚至让研究者本人都感到意外。', 'outcome');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impact-1', 'impact', 'Researchers are still measuring the impact of noise on young children''s learning.', '研究者仍在衡量噪音对幼儿学习的影响。', 'impact');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impact-2', 'impact', 'Rising sea temperatures have impacted coral reefs across the region.', '不断上升的海水温度已经影响到整个地区的珊瑚礁。', 'impacted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('effect-1', 'effect', 'The new law had little effect on the number of road accidents.', '新法律对交通事故数量几乎没有影响。', 'effect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affect-1', 'affect', 'Lack of sleep can affect both memory and the ability to make decisions.', '睡眠不足会影响记忆力和决策能力。', 'affect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('influence-1', 'influence', 'Parents have a strong influence on the eating habits of their children.', '父母对孩子的饮食习惯有很大影响。', 'influence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('influence-2', 'influence', 'Advertising can influence what people choose to buy without their realising it.', '广告可以在不知不觉中影响人们的购买选择。', 'influence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('result-in-1', 'result-in', 'A small rise in temperature could result in the loss of many species.', '气温小幅上升可能导致许多物种消失。', 'result in');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('result-from-1', 'result-from', 'Many health problems result from a poor diet and too little exercise.', '许多健康问题是由不良饮食和缺乏运动导致的。', 'result from');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lead-to-1', 'lead-to', 'Too much screen time may lead to poor sleep among teenagers.', '过多使用电子屏幕可能导致青少年睡眠不佳。', 'lead to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('give-rise-to-1', 'give-rise-to', 'The growth of trade gave rise to a new class of wealthy merchants.', '贸易发展催生了一个新的富商阶层。', 'gave rise to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contribute-to-1', 'contribute-to', 'Several factors contribute to the decline of bee populations.', '有几个因素促成了蜜蜂数量的减少。', 'contribute to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stem-from-1', 'stem-from', 'Many of the city''s traffic problems stem from its narrow medieval streets.', '这座城市的许多交通问题源于狭窄的中世纪街道。', 'stem from');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('derive-from-1', 'derive-from', 'Many English words derive from Latin or from ancient Greek.', '许多英语单词来源于拉丁语或古希腊语。', 'derive from');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trigger-1', 'trigger', 'Even a small earthquake can trigger a large landslide on steep slopes.', '即使是小地震,也可能在陡坡上引发大规模滑坡。', 'trigger');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trigger-2', 'trigger', 'Stress is a common trigger for headaches among office workers.', '压力是办公室职员头痛的常见诱因。', 'trigger');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('induce-1', 'induce', 'The drug was used to induce sleep in patients before an operation.', '这种药曾用于在手术前诱导患者入睡。', 'induce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('generate-1', 'generate', 'Wind farms now generate a large share of the country''s electricity.', '风电场现在产生该国很大一部分电力。', 'generate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('yield-1', 'yield', 'The new variety of rice can yield twice as much as older types.', '这种新水稻品种的产量可达旧品种的两倍。', 'yield');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('yield-2', 'yield', 'The wheat yield fell sharply during the years of low rainfall.', '在降雨少的年份,小麦产量急剧下降。', 'yield');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('account-for-1', 'account-for', 'Differences in diet may account for the lower rates of heart disease.', '饮食差异也许能解释心脏病发病率较低的原因。', 'account for');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('account-for-2', 'account-for', 'Older people now account for a quarter of the town''s population.', '老年人现在占该镇人口的四分之一。', 'account for');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('due-to-1', 'due-to', 'The population of the village fell due to a lack of jobs.', '由于缺少工作机会,这个村庄的人口减少了。', 'due to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('owing-to-1', 'owing-to', 'Owing to the dry climate, very few plants can grow in this region.', '由于气候干燥,这一地区几乎没有植物能够生长。', 'Owing to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thereby-1', 'thereby', 'Trees provide shade for buildings, thereby reducing the need for air conditioning.', '树木为建筑遮阴,从而减少了对空调的需求。', 'thereby');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thus-1', 'thus', 'The river changed course, and thus the town lost its main trade route.', '河流改道了,这座城镇因此失去了主要的贸易路线。', 'thus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hence-1', 'hence', 'The soil here is very poor; hence the small number of farms.', '这里的土壤非常贫瘠,因此农场很少。', 'hence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consequently-1', 'consequently', 'Prices rose sharply, and consequently many families could not afford bread.', '价格急剧上涨,因此许多家庭买不起面包。', 'consequently');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('therefore-1', 'therefore', 'The sample was small, and therefore the results should be treated carefully.', '样本量较小,所以应谨慎看待这些结果。', 'therefore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('whereas-1', 'whereas', 'Some birds fly south in winter, whereas others remain in the same area.', '有些鸟冬天飞往南方,而另一些则留在原地。', 'whereas');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('while-1', 'while', 'While the first study found a clear link, the second did not.', '第一项研究发现了明显的关联,然而第二项没有。', 'While');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('although-1', 'although', 'Although the plant looks dead in summer, its roots remain alive underground.', '尽管这种植物夏天看起来已经枯死,但它的根在地下依然活着。', 'Although');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('despite-1', 'despite', 'Despite years of research, the origin of the language remains unknown.', '尽管经过多年研究,这种语言的起源仍然不明。', 'Despite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nevertheless-1', 'nevertheless', 'The evidence is limited; nevertheless, it points in a clear direction.', '证据有限,然而它指向了一个明确的方向。', 'nevertheless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nonetheless-1', 'nonetheless', 'The journey was dangerous, but many people chose to make it nonetheless.', '这段旅程很危险,尽管如此,许多人还是选择了出发。', 'nonetheless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notwithstanding-1', 'notwithstanding', 'Notwithstanding these difficulties, the project was completed ahead of schedule.', '尽管有这些困难,项目还是提前完成了。', 'Notwithstanding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('moreover-1', 'moreover', 'The new bridge is cheaper to build; moreover, it requires little maintenance.', '新桥造价更低,此外,它几乎不需要维护。', 'moreover');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('furthermore-1', 'furthermore', 'The drug is effective; furthermore, it has very few side effects.', '这种药很有效,此外,它的副作用也很少。', 'furthermore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-addition-1', 'in-addition', 'In addition to food, the forest provides local people with medicine.', '除了食物,森林还为当地人提供药物。', 'In addition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('likewise-1', 'likewise', 'Children copy the speech of their parents, and they likewise copy their behaviour.', '孩子模仿父母说话,同样也模仿他们的行为。', 'likewise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('similarly-1', 'similarly', 'Bats use sound to find food; similarly, dolphins hunt using echoes.', '蝙蝠利用声音寻找食物,类似地,海豚也靠回声捕猎。', 'similarly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conversely-1', 'conversely', 'Warm air rises; conversely, cold air tends to sink towards the ground.', '热空气上升,相反地,冷空气往往下沉到地面。', 'conversely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-contrast-1', 'in-contrast', 'In contrast, the northern part of the country receives very little rain.', '相比之下,该国北部的降雨量很少。', 'In contrast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('on-the-contrary-1', 'on-the-contrary', 'The noise did not harm the birds; on the contrary, they seemed unaffected.', '噪音并没有伤害这些鸟,恰恰相反,它们似乎完全不受影响。', 'on the contrary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alternatively-1', 'alternatively', 'Waste can be burned for energy or, alternatively, turned into fertiliser.', '废弃物可以焚烧发电,或者制成肥料。', 'alternatively');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('namely-1', 'namely', 'The study focused on two groups, namely farmers and factory workers.', '这项研究聚焦于两个群体,即农民和工厂工人。', 'namely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-terms-of-1', 'in-terms-of', 'In terms of cost, solar power is now cheaper than coal in many countries.', '就成本而言,在许多国家太阳能现在比煤炭便宜。', 'In terms of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('with-regard-to-1', 'with-regard-to', 'Little is known with regard to the diet of these early humans.', '关于这些早期人类的饮食,人们所知甚少。', 'with regard to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-respect-of-1', 'in-respect-of', 'The two languages differ in respect of their grammar and their sound systems.', '这两种语言在语法和语音系统方面有所不同。', 'in respect of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('provided-that-1', 'provided-that', 'The species can survive, provided that its habitat is protected.', '只要栖息地得到保护,这个物种就能存活下来。', 'provided that');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unless-1', 'unless', 'Many of these languages will disappear unless action is taken soon.', '除非尽快采取行动,否则这些语言中的许多将会消失。', 'unless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('whereby-1', 'whereby', 'Photosynthesis is the process whereby plants turn sunlight into food.', '光合作用是植物把阳光转化为养分的过程。', 'whereby');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subsequently-1', 'subsequently', 'The disease first appeared in Asia and subsequently spread to Europe.', '这种疾病最早出现在亚洲,随后传到了欧洲。', 'subsequently');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('previously-1', 'previously', 'The fossils belong to a species that was previously unknown to science.', '这些化石属于一个此前科学界未知的物种。', 'previously');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('simultaneously-1', 'simultaneously', 'Bees can carry pollen and collect nectar simultaneously as they move between flowers.', '蜜蜂在花间穿行时,能够同时携带花粉并采集花蜜。', 'simultaneously');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ultimately-1', 'ultimately', 'The choice of treatment is ultimately a matter for the patient to decide.', '治疗方案最终要由患者决定。', 'ultimately');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('initially-1', 'initially', 'The project was initially planned to last just two years.', '这个项目最初计划只持续两年。', 'initially');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eventually-1', 'eventually', 'The small settlement eventually grew into one of the region''s largest cities.', '这个小定居点最终发展成该地区最大的城市之一。', 'eventually');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prior-to-1', 'prior-to', 'Few people in the area could read prior to the opening of the school.', '学校开办之前,当地很少有人识字。', 'prior to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correspondingly-1', 'correspondingly', 'As incomes rise, spending on leisure tends to increase correspondingly.', '随着收入增加,休闲支出往往也相应增长。', 'correspondingly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accordingly-1', 'accordingly', 'Conditions change quickly, and farmers must adjust their methods accordingly.', '环境变化很快,农民必须相应地调整耕作方法。', 'accordingly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inevitably-1', 'inevitably', 'Rapid growth inevitably puts pressure on housing and public transport.', '快速增长不可避免地给住房和公共交通带来压力。', 'inevitably');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arguably-1', 'arguably', 'The printing press was arguably the most important invention of that period.', '可以说,印刷机是那个时期最重要的发明。', 'arguably');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amongst-1', 'amongst', 'The custom is still common amongst people in the northern islands.', '这一习俗在北部岛屿的人们之中仍很常见。', 'amongst');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('precede-1', 'precede', 'Changes in animal behaviour may precede a major earthquake by several days.', '动物行为的变化可能先于大地震几天出现。', 'precede');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('afterwards-1', 'afterwards', 'The volcano erupted in 1815, and the climate cooled for several years afterwards.', '这座火山于 1815 年喷发,此后几年气候变冷。', 'afterwards');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contrary-1', 'contrary', 'Contrary to popular belief, camels do not store water in their humps.', '与普遍看法相反,骆驼的驼峰并不储水。', 'Contrary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contrary-2', 'contrary', 'There is no evidence to the contrary, so the theory is still accepted.', '没有相反的证据,所以这一理论仍被接受。', 'contrary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sometime-1', 'sometime', 'The city was abandoned sometime in the twelfth century, but nobody knows why.', '这座城市在十二世纪的某个时候被遗弃,但没人知道原因。', 'sometime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('whoever-1', 'whoever', 'Whoever built this wall had a good knowledge of engineering.', '无论这堵墙是谁建的,此人都很懂工程学。', 'Whoever');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('whichever-1', 'whichever', 'Animals usually take whichever route uses the least energy.', '动物通常会选择耗能最少的路线,无论是哪一条。', 'whichever');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crucial-1', 'crucial', 'Bees play a crucial role in the production of many food crops.', '蜜蜂在许多粮食作物的生产中起着关键作用。', 'crucial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vital-1', 'vital', 'Clean water is vital for the health of any community.', '清洁的水对任何社区的健康都至关重要。', 'vital');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('essential-1', 'essential', 'Iron is essential for the production of healthy red blood cells.', '铁对于生成健康的红细胞是必要的。', 'essential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fundamental-1', 'fundamental', 'There is a fundamental difference between human language and animal signals.', '人类语言和动物信号之间有根本的区别。', 'fundamental');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indispensable-1', 'indispensable', 'Mobile phones have become an indispensable part of modern life.', '手机已成为现代生活中不可或缺的一部分。', 'indispensable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paramount-1', 'paramount', 'Safety is of paramount importance in the design of nuclear power stations.', '在核电站设计中,安全是最重要的。', 'paramount');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('predominant-1', 'predominant', 'Rice is the predominant crop in the wet southern part of the country.', '水稻是该国潮湿南部的主要作物。', 'predominant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prevalent-1', 'prevalent', 'This disease is more prevalent in hot and humid parts of the world.', '这种疾病在世界上炎热潮湿的地区更普遍。', 'prevalent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('widespread-1', 'widespread', 'The use of the plough became widespread across Europe in the Middle Ages.', '中世纪时,犁在欧洲各地得到了广泛使用。', 'widespread');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('common-1', 'common', 'Short-sightedness has become increasingly common among children in cities.', '近视在城市儿童中变得越来越常见。', 'common');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rare-1', 'rare', 'The rare plant grows only on a few mountains in the south.', '这种罕见的植物只生长在南部的几座山上。', 'rare');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unique-1', 'unique', 'The island is home to a unique species of lizard found nowhere else.', '这座岛上有一种独特的蜥蜴,在其他地方都找不到。', 'unique');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distinct-1', 'distinct', 'The study identified three distinct stages in the development of speech.', '这项研究确定了语言发展的三个不同阶段。', 'distinct');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distinctive-1', 'distinctive', 'The bird is easily recognised by its distinctive red tail feathers.', '这种鸟很容易凭借独特的红色尾羽辨认出来。', 'distinctive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inherent-1', 'inherent', 'There are risks inherent in any form of deep-sea exploration.', '任何形式的深海探索都有固有的风险。', 'inherent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intrinsic-1', 'intrinsic', 'Students learn better when they find an intrinsic interest in the subject.', '学生对学科有内在兴趣时学得更好。', 'intrinsic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('potential-1', 'potential', 'The potential benefits of the new treatment are still being studied.', '这种新疗法的潜在益处仍在研究之中。', 'potential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('potential-2', 'potential', 'Tidal energy has great potential as a clean source of electricity.', '潮汐能作为清洁电力来源具有巨大潜力。', 'potential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feasible-1', 'feasible', 'It is not yet feasible to store large amounts of electricity cheaply.', '廉价储存大量电力目前还不可行。', 'feasible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('viable-1', 'viable', 'Electric buses are now a viable alternative to those powered by diesel.', '电动公交车现在是柴油公交车的可行替代品。', 'viable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('practical-1', 'practical', 'The method works well in theory but has few practical uses.', '这种方法理论上很好,但实际用途很少。', 'practical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pragmatic-1', 'pragmatic', 'Local leaders took a pragmatic approach and worked with both sides.', '当地领导人采取了务实的做法,与双方都展开合作。', 'pragmatic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('efficient-1', 'efficient', 'Modern engines are far more efficient than those of fifty years ago.', '现代发动机比五十年前的高效得多。', 'efficient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('effective-1', 'effective', 'Vaccination remains the most effective way of preventing the disease.', '接种疫苗仍是预防这种疾病最有效的方法。', 'effective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beneficial-1', 'beneficial', 'A moderate amount of exercise is beneficial for people of all ages.', '适量运动对各个年龄段的人都有益。', 'beneficial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detrimental-1', 'detrimental', 'Too much noise can be detrimental to children''s ability to concentrate.', '过多噪音可能损害儿童的注意力。', 'detrimental');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harmful-1', 'harmful', 'Many cleaning products contain chemicals that are harmful to river life.', '许多清洁产品含有对河流生物有害的化学物质。', 'harmful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adverse-1', 'adverse', 'Most patients taking the drug reported no adverse effects.', '大多数服用这种药的患者报告没有不良反应。', 'adverse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('negative-1', 'negative', 'The new road had a negative effect on the local bird population.', '新公路对当地鸟类数量产生了负面影响。', 'negative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('positive-1', 'positive', 'Regular contact with nature has a positive effect on mental health.', '经常接触大自然对心理健康有积极影响。', 'positive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('profound-1', 'profound', 'The invention of writing had a profound effect on human society.', '文字的发明对人类社会产生了深远影响。', 'profound');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('far-reaching-1', 'far-reaching', 'The discovery of antibiotics had far-reaching consequences for modern medicine.', '抗生素的发现对现代医学产生了深远的影响。', 'far-reaching');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('long-term-1', 'long-term', 'Little is known about the long-term effects of this chemical on humans.', '人们对这种化学物质对人体的长期影响知之甚少。', 'long-term');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('short-term-1', 'short-term', 'The drug provides short-term relief but does not cure the illness.', '这种药能短期缓解症状,但无法治愈疾病。', 'short-term');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('temporary-1', 'temporary', 'Workers lived in temporary housing while the new town was being built.', '新城建设期间,工人们住在临时住房里。', 'temporary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('permanent-1', 'permanent', 'Exposure to very loud noise can cause permanent damage to hearing.', '暴露在极大的噪音中可能造成永久性听力损伤。', 'permanent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sustainable-1', 'sustainable', 'Farmers are being encouraged to adopt more sustainable methods of fishing.', '人们鼓励渔民采用更可持续的捕鱼方法。', 'sustainable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appropriate-1', 'appropriate', 'Teachers must choose materials that are appropriate for the age of the children.', '教师必须选择适合孩子年龄的教材。', 'appropriate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adequate-1', 'adequate', 'Many people in the region still do not have adequate access to clean water.', '该地区的许多人仍然无法获得足够的清洁水。', 'adequate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sufficient-1', 'sufficient', 'There is not yet sufficient evidence to support this explanation.', '目前还没有充足的证据支持这一解释。', 'sufficient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insufficient-1', 'insufficient', 'Insufficient funding forced the museum to close two of its galleries.', '资金不足迫使博物馆关闭了两个展厅。', 'Insufficient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excessive-1', 'excessive', 'Excessive use of fertiliser can pollute nearby rivers and lakes.', '过度使用化肥会污染附近的河流和湖泊。', 'Excessive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('minimal-1', 'minimal', 'The new design causes minimal disturbance to the surrounding environment.', '新设计对周围环境的干扰极小。', 'minimal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maximum-1', 'maximum', 'Plants reach their maximum height after about three months of growth.', '植物生长约三个月后达到最大高度。', 'maximum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optimal-1', 'optimal', 'The optimal temperature for growing this crop is about twenty-five degrees.', '种植这种作物的最佳温度约为二十五度。', 'optimal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ideal-1', 'ideal', 'The warm, shallow water provides ideal conditions for young fish.', '温暖的浅水为幼鱼提供了理想的环境。', 'ideal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('complex-1', 'complex', 'The human brain is the most complex organ in the body.', '人脑是身体中最复杂的器官。', 'complex');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sophisticated-1', 'sophisticated', 'The ancient Egyptians developed a sophisticated system for moving water to their fields.', '古埃及人发展出一套精密的系统,把水引到田地里。', 'sophisticated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('straightforward-1', 'straightforward', 'The answer to this question is not as straightforward as it seems.', '这个问题的答案并不像看起来那么简单。', 'straightforward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('explicit-1', 'explicit', 'The report makes no explicit reference to the cost of the project.', '报告没有明确提及项目的成本。', 'explicit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('implicit-1', 'implicit', 'There is an implicit assumption in the theory that people always act rationally.', '这个理论隐含着一个假定:人总是理性行事。', 'implicit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ambiguous-1', 'ambiguous', 'The results of the test were ambiguous and open to different interpretations.', '测试结果模棱两可,可以有不同的解释。', 'ambiguous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obvious-1', 'obvious', 'The benefits of the new system were not immediately obvious to farmers.', '新系统的好处对农民来说并非立刻就能看出来。', 'obvious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apparent-1', 'apparent', 'It soon became apparent that the water was no longer safe to drink.', '很快人们就发现,这些水已经不能安全饮用了。', 'apparent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apparent-2', 'apparent', 'The apparent increase in cases may simply reflect better testing.', '病例表面上的增加可能只是反映了检测手段的改善。', 'apparent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evident-1', 'evident', 'The effects of the drought were evident in the dry fields.', '干旱的影响在干涸的田地里十分明显。', 'evident');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notable-1', 'notable', 'One notable feature of this building is its unusual roof.', '这座建筑值得注意的一个特点是不同寻常的屋顶。', 'notable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remarkable-1', 'remarkable', 'Some birds have a remarkable ability to find their way home.', '有些鸟具有非凡的认路回家的能力。', 'remarkable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('striking-1', 'striking', 'There is a striking similarity between the two languages.', '这两种语言有显著的相似之处。', 'striking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('considerably-1', 'considerably', 'The cost of solar panels has fallen considerably over the past decade.', '过去十年,太阳能电池板的成本大幅下降。', 'considerably');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relatively-1', 'relatively', 'The disease is relatively rare among people under the age of forty.', '这种疾病在四十岁以下人群中相对少见。', 'relatively');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comparatively-1', 'comparatively', 'The town remained comparatively small until the arrival of the railway.', '铁路通车之前,这座城镇一直比较小。', 'comparatively');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('largely-1', 'largely', 'The success of the project was largely due to local support.', '这个项目的成功在很大程度上归功于当地人的支持。', 'largely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('primarily-1', 'primarily', 'This species feeds primarily on insects found under the bark of trees.', '这种动物主要以树皮下的昆虫为食。', 'primarily');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('predominantly-1', 'predominantly', 'The workforce in the factory was predominantly female until the 1950s.', '直到 20 世纪 50 年代,这家工厂的工人主要是女性。', 'predominantly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('partially-1', 'partially', 'The ancient wall has been partially destroyed by centuries of wind and rain.', '几个世纪的风雨已使这堵古墙部分毁坏。', 'partially');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entirely-1', 'entirely', 'The building is powered entirely by energy from the sun.', '这座建筑完全由太阳能供电。', 'entirely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('virtually-1', 'virtually', 'Virtually all the land in the valley is now used for farming.', '山谷里几乎所有的土地现在都用于耕作。', 'Virtually');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('merely-1', 'merely', 'These figures are merely estimates and may not reflect the real situation.', '这些数字仅仅是估算,可能不反映真实情况。', 'merely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solely-1', 'solely', 'The decision should not be based solely on the cost of the project.', '这项决定不应只基于项目成本。', 'solely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('specifically-1', 'specifically', 'The programme was designed specifically for children with reading difficulties.', '这个项目是专门为有阅读困难的儿童设计的。', 'specifically');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('particularly-1', 'particularly', 'The city''s air quality is particularly poor during the winter months.', '这座城市的空气质量在冬季特别差。', 'particularly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notably-1', 'notably', 'Some countries, notably Denmark, now produce most of their power from wind.', '一些国家,尤其是丹麦,现在大部分电力来自风能。', 'notably');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('increasingly-1', 'increasingly', 'Young people are increasingly choosing to live in smaller homes.', '年轻人越来越多地选择住小户型。', 'increasingly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unprecedented-1', 'unprecedented', 'The city experienced unprecedented growth during the last century.', '上个世纪,这座城市经历了前所未有的增长。', 'unprecedented');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overwhelming-1', 'overwhelming', 'There is overwhelming evidence that smoking damages the lungs.', '有压倒性的证据表明吸烟会损害肺部。', 'overwhelming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prevailing-1', 'prevailing', 'The prevailing view at the time was that bad air caused the illness.', '当时盛行的观点是这种疾病由污浊的空气引起。', 'prevailing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extensive-1', 'extensive', 'The fire caused extensive damage to the forests in the north.', '这场大火对北部森林造成了大面积破坏。', 'extensive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invaluable-1', 'invaluable', 'These old diaries are an invaluable source of information for historians.', '这些旧日记对历史学家来说是极其宝贵的信息来源。', 'invaluable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('versatile-1', 'versatile', 'Bamboo is a versatile material used for building, cooking and making paper.', '竹子是一种多用途材料,可用于建筑、烹饪和造纸。', 'versatile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('specialised-1', 'specialised', 'The work requires specialised equipment that few laboratories can afford.', '这项工作需要专门的设备,很少有实验室买得起。', 'specialised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diverse-1', 'diverse', 'The region has a diverse population speaking more than twenty languages.', '该地区人口多样,使用二十多种语言。', 'diverse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exclusive-1', 'exclusive', 'The club was once exclusive to men from wealthy families.', '这家俱乐部曾经只面向富裕家庭的男性。', 'exclusive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dominant-1', 'dominant', 'English has become the dominant language of international science.', '英语已成为国际科学界的主导语言。', 'dominant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('severe-1', 'severe', 'The region suffered a severe drought that lasted for almost three years.', '该地区遭受了持续近三年的严重干旱。', 'severe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rigid-1', 'rigid', 'The school''s rigid rules left little room for creative teaching.', '学校僵化的规定几乎没有留下创造性教学的空间。', 'rigid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stringent-1', 'stringent', 'The law introduced stringent controls on the use of pesticides.', '这项法律对农药使用实施了严格的管控。', 'stringent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impartial-1', 'impartial', 'The committee must remain impartial when judging the competing proposals.', '评审相互竞争的提案时,委员会必须保持公正。', 'impartial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('misleading-1', 'misleading', 'Averages can be misleading when a few very high values are included.', '包含少数极高数值时,平均数可能具有误导性。', 'misleading');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inconceivable-1', 'inconceivable', 'A century ago, instant global communication would have seemed inconceivable to most people.', '一个世纪前,大多数人会觉得全球即时通信难以想象。', 'inconceivable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('threat-1', 'threat', 'Rising sea levels pose a serious threat to low-lying islands.', '海平面上升对低洼岛屿构成严重威胁。', 'threat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hazard-1', 'hazard', 'Falling rocks are a constant hazard for people working in the mine.', '落石对矿工来说始终是一种危险。', 'hazard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jeopardy-1', 'jeopardy', 'Thousands of jobs were put in jeopardy when the factory lost its main customer.', '工厂失去主要客户后,数千个工作岗位陷入危险境地。', 'jeopardy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deliberately-1', 'deliberately', 'Some early farmers deliberately burned forests to clear land for crops.', '一些早期农民故意焚烧森林,开垦土地种庄稼。', 'deliberately');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('readily-1', 'readily', 'The metal reacts readily with water, so it must be stored in oil.', '这种金属容易与水发生反应,所以必须存放在油中。', 'readily');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prominent-1', 'prominent', 'Women played a prominent role in the early history of the movement.', '女性在这场运动的早期历史中发挥了突出的作用。', 'prominent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('purely-1', 'purely', 'The decision to close the school was made for purely financial reasons.', '关闭学校的决定完全是出于财务原因。', 'purely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outer-1', 'outer', 'The outer layer of the skin protects the body from infection.', '皮肤的外层保护身体免受感染。', 'outer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bound-1', 'bound', 'With so many cars on the road, traffic problems are bound to get worse.', '路上汽车这么多,交通问题必定会恶化。', 'bound');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('naked-1', 'naked', 'Many of these stars cannot be seen with the naked eye.', '这些恒星中有许多用肉眼是看不见的。', 'naked');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('formally-1', 'formally', 'The treaty was formally signed by both countries in 1848.', '两国于 1848 年正式签署了这项条约。', 'formally');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('superior-1', 'superior', 'The new material proved superior to steel in almost every test.', '事实证明,这种新材料在几乎所有测试中都优于钢材。', 'superior');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('superior-2', 'superior', 'Employees often feel unable to disagree openly with their superiors.', '员工常常觉得无法公开反对上级。', 'superiors');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subtle-1', 'subtle', 'Even subtle changes in temperature can affect how these insects behave.', '即使温度的细微变化,也会影响这些昆虫的行为。', 'subtle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('realistic-1', 'realistic', 'It is not realistic to expect all cars to be electric within ten years.', '指望十年内所有汽车都变成电动的,并不现实。', 'realistic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correctly-1', 'correctly', 'Only a third of participants answered all the questions correctly.', '只有三分之一的参与者答对了所有问题。', 'correctly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('locally-1', 'locally', 'The restaurant uses only vegetables that are grown locally.', '这家餐厅只用当地种植的蔬菜。', 'locally');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('progressive-1', 'progressive', 'The city was known for its progressive attitude towards women''s education.', '这座城市以对女性教育的进步态度而闻名。', 'progressive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('progressive-2', 'progressive', 'The illness causes a progressive loss of memory over many years.', '这种疾病会在多年间造成记忆力的渐进性衰退。', 'progressive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indirect-1', 'indirect', 'Pollution has an indirect effect on birds by reducing their supply of food.', '污染通过减少食物来源,对鸟类产生间接影响。', 'indirect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vague-1', 'vague', 'Early descriptions of the disease were too vague to be useful.', '早期对这种疾病的描述过于模糊,没有什么用处。', 'vague');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incredibly-1', 'incredibly', 'Spider silk is incredibly strong for such a light material.', '作为如此轻的材料,蛛丝极其坚韧。', 'incredibly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('actively-1', 'actively', 'Students learn more when they take part actively in discussions.', '学生积极参与讨论时学到的更多。', 'actively');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('irrelevant-1', 'irrelevant', 'Much of the information in the report is irrelevant to the main question.', '报告中的许多信息与主要问题无关。', 'irrelevant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supposedly-1', 'supposedly', 'The treatment is supposedly safe, but few long-term studies have been done.', '据说这种疗法是安全的,但很少有长期研究。', 'supposedly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terribly-1', 'terribly', 'The early flying machines were terribly difficult to control.', '早期的飞行器非常难操控。', 'terribly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('selective-1', 'selective', 'Bees are selective about which flowers they visit for food.', '蜜蜂对采食的花朵很挑剔。', 'selective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('backward-1', 'backward', 'In the nineteenth century, the region was seen as economically backward.', '在十九世纪,这一地区被视为经济落后。', 'backward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('problematic-1', 'problematic', 'Comparing data from different countries can be problematic for researchers.', '比较不同国家的数据对研究者来说可能有问题。', 'problematic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obscure-1', 'obscure', 'The word comes from an obscure dialect spoken in the far north.', '这个词来自远北地区一种鲜为人知的方言。', 'obscure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obscure-2', 'obscure', 'Thick clouds often obscure the top of the mountain from view.', '厚厚的云层常常遮住山顶。', 'obscure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nicely-1', 'nicely', 'The findings fit nicely with what we already know about memory.', '这些发现与我们已知的记忆知识很好地吻合。', 'nicely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spontaneous-1', 'spontaneous', 'Children''s spontaneous play helps them to develop social skills.', '儿童自发的游戏有助于发展社交能力。', 'spontaneous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trivial-1', 'trivial', 'Decisions that seem trivial can have large effects over a long period.', '看似琐碎的决定,长期来看可能产生很大影响。', 'trivial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peripheral-1', 'peripheral', 'The issue was once considered peripheral to the main concerns of economists.', '这个问题曾被认为对经济学家的主要关注点而言只是次要的。', 'peripheral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tricky-1', 'tricky', 'Measuring happiness is a tricky task for any social scientist.', '对任何社会科学家来说,衡量幸福都是一项棘手的任务。', 'tricky');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unstable-1', 'unstable', 'The cliffs along this coast are unstable and could fall at any time.', '这段海岸的悬崖不稳定,随时可能坍塌。', 'unstable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lateral-1', 'lateral', 'The tree has strong lateral roots that spread close to the surface.', '这种树有粗壮的侧根,贴近地表生长。', 'lateral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coherent-1', 'coherent', 'The author fails to present a coherent explanation of the data.', '作者未能对数据作出条理清楚的解释。', 'coherent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suitable-1', 'suitable', 'Much of the land in the north is not suitable for growing crops.', '北部的许多土地不适合种植庄稼。', 'suitable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supreme-1', 'supreme', 'The emperor held supreme power over all parts of the empire.', '皇帝对帝国各地拥有最高权力。', 'supreme');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unlikely-1', 'unlikely', 'It is unlikely that this species will survive without human help.', '没有人类的帮助,这个物种不太可能存活。', 'unlikely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elsewhere-1', 'elsewhere', 'The plant grows on this island but has not been found elsewhere in Europe.', '这种植物生长在这座岛上,在欧洲其他地方都没有发现。', 'elsewhere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('somewhat-1', 'somewhat', 'The results of later surveys were somewhat different from those of the first.', '后来几次调查的结果与第一次略有不同。', 'somewhat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('typical-1', 'typical', 'A typical nest contains between three and five eggs.', '一个典型的巢里有三到五枚蛋。', 'typical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('external-1', 'external', 'External factors, such as the weather, can affect the results of the test.', '天气等外部因素可能影响测试结果。', 'External');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contemporary-1', 'contemporary', 'Contemporary artists are exploring new ways of using digital technology.', '当代艺术家正在探索运用数字技术的新方式。', 'Contemporary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contemporary-2', 'contemporary', 'Shakespeare and his contemporaries wrote many plays for the London stage.', '莎士比亚和与他同时代的人为伦敦舞台写了许多戏剧。', 'contemporaries');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barely-1', 'barely', 'The village is barely visible from the road because of the trees.', '由于树木遮挡,从公路上几乎看不见这个村庄。', 'barely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unusual-1', 'unusual', 'It is unusual for this type of bird to build a nest on the ground.', '这种鸟在地面筑巢是不寻常的。', 'unusual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('voluntary-1', 'voluntary', 'Participation in the study was voluntary, and people could leave at any time.', '参与这项研究是自愿的,人们可以随时退出。', 'voluntary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intense-1', 'intense', 'The intense heat of the fire melted the metal parts of the building.', '大火的高温熔化了建筑的金属部件。', 'intense');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('visible-1', 'visible', 'The effects of pollution are clearly visible on the old stone walls.', '污染的影响在古老的石墙上清晰可见。', 'visible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('radical-1', 'radical', 'The new technology brought about a radical change in the way people work.', '新技术使人们的工作方式发生了根本的变化。', 'radical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pure-1', 'pure', 'The cave contains pure water that has been filtered through the rock.', '洞穴里有经过岩石过滤的纯净水。', 'pure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('literally-1', 'literally', 'The name of the town literally means ''place by the river''.', '这个城镇的名字字面意思是“河边的地方”。', 'literally');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extreme-1', 'extreme', 'Few plants can survive the extreme cold of the Arctic winter.', '很少有植物能在北极冬天的极端严寒中存活。', 'extreme');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('presumably-1', 'presumably', 'The tools were found by the river, presumably because people fished there.', '这些工具是在河边发现的,大概是因为人们在那里捕鱼。', 'presumably');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genuine-1', 'genuine', 'Experts confirmed that the painting was a genuine work by the artist.', '专家确认这幅画是这位画家的真迹。', 'genuine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distant-1', 'distant', 'The light from distant stars can take millions of years to reach us.', '来自遥远恒星的光可能要数百万年才能到达我们这里。', 'distant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raw-1', 'raw', 'The factory imports raw materials and turns them into finished goods.', '这家工厂进口原材料,把它们加工成成品。', 'raw');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ongoing-1', 'ongoing', 'Ongoing research suggests that the drug may also help with memory loss.', '正在进行的研究表明,这种药也可能有助于改善记忆减退。', 'Ongoing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('undoubtedly-1', 'undoubtedly', 'The railway undoubtedly helped the town''s economy to grow.', '铁路无疑促进了这座城镇的经济增长。', 'undoubtedly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flexible-1', 'flexible', 'Young children''s brains are more flexible than those of adults.', '幼儿的大脑比成年人的更灵活。', 'flexible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inadequate-1', 'inadequate', 'Inadequate lighting in the classroom may affect students'' eyesight.', '教室照明不足可能影响学生的视力。', 'Inadequate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('underlying-1', 'underlying', 'Doctors must treat the underlying cause rather than just the symptoms.', '医生必须治疗根本病因,而不只是症状。', 'underlying');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sheer-1', 'sheer', 'The sheer size of the building impressed visitors from all over the world.', '这座建筑的庞大规模本身就令世界各地的游客赞叹。', 'sheer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sheer-2', 'sheer', 'The birds nest on sheer cliffs high above the sea.', '这些鸟把巢筑在高高的海上峭壁上。', 'sheer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harsh-1', 'harsh', 'Few animals can survive the harsh conditions of the desert in summer.', '很少有动物能在夏季沙漠的严酷环境中生存。', 'harsh');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reluctant-1', 'reluctant', 'Many farmers were reluctant to change the methods they had always used.', '许多农民不愿改变一直使用的方法。', 'reluctant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seemingly-1', 'seemingly', 'A seemingly simple task can involve many different parts of the brain.', '一项表面上简单的任务可能涉及大脑的许多不同区域。', 'seemingly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('random-1', 'random', 'Participants were chosen at random from a list of local residents.', '参与者是从当地居民名单中随机选出的。', 'random');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invisible-1', 'invisible', 'Air pollution is often invisible, but it can seriously damage health.', '空气污染往往看不见,但会严重损害健康。', 'invisible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fierce-1', 'fierce', 'There is fierce competition for land between farmers and developers.', '农民和开发商之间对土地的争夺十分激烈。', 'fierce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bold-1', 'bold', 'The architect''s bold design was criticised by many people at the time.', '这位建筑师大胆的设计在当时受到许多人的批评。', 'bold');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stiff-1', 'stiff', 'Sitting for long hours can leave the muscles of the back stiff.', '久坐会使背部肌肉僵硬。', 'stiff');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('awkward-1', 'awkward', 'Moving such a heavy statue was an awkward and dangerous task.', '搬运这么重的雕像既笨拙又危险。', 'awkward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invariably-1', 'invariably', 'In these conditions, the experiment invariably produced the same result.', '在这些条件下,实验总是产生相同的结果。', 'invariably');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forthcoming-1', 'forthcoming', 'Further details of the study will appear in a forthcoming article.', '这项研究的更多细节将在一篇即将发表的文章中公布。', 'forthcoming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hitherto-1', 'hitherto', 'The cave contained hitherto unknown species of insects and spiders.', '洞穴里有迄今未知的昆虫和蜘蛛物种。', 'hitherto');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intimate-1', 'intimate', 'Language has an intimate connection with a people''s sense of identity.', '语言与一个民族的身份认同有着密切的联系。', 'intimate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secular-1', 'secular', 'The country''s schools became fully secular at the end of the nineteenth century.', '这个国家的学校在十九世纪末完全世俗化了。', 'secular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('worthwhile-1', 'worthwhile', 'Learning a second language is a worthwhile activity at any age.', '无论什么年龄,学习第二语言都是值得的。', 'worthwhile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sympathetic-1', 'sympathetic', 'Local people were sympathetic to the workers and gave them food.', '当地人同情这些工人,给他们送去了食物。', 'sympathetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anonymous-1', 'anonymous', 'All the answers in the survey were kept anonymous to protect the participants.', '调查的所有答案都是匿名的,以保护参与者。', 'anonymous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fatal-1', 'fatal', 'Without treatment, the disease is fatal in about half of all cases.', '如果不治疗,这种疾病约有一半的病例是致命的。', 'fatal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peculiar-1', 'peculiar', 'The peculiar shape of the rocks was caused by the wind.', '这些岩石奇特的形状是风造成的。', 'peculiar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immense-1', 'immense', 'The dam has brought immense benefits to farmers along the river.', '这座大坝给沿河农民带来了巨大的好处。', 'immense');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eligible-1', 'eligible', 'Only people over eighteen were eligible to take part in the study.', '只有十八岁以上的人才有资格参加这项研究。', 'eligible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intact-1', 'intact', 'The ship was found almost intact on the bottom of the lake.', '这艘船在湖底被发现时几乎完好无损。', 'intact');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('doubtful-1', 'doubtful', 'It is doubtful whether the species could survive in the wild.', '这个物种能否在野外存活还不确定。', 'doubtful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brutal-1', 'brutal', 'Workers in early coal mines often faced brutal conditions underground.', '早期煤矿的工人在地下常常面临残酷的条件。', 'brutal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deliberate-1', 'deliberate', 'Researchers believe the fire was a deliberate attempt to clear the land.', '研究者认为这场大火是有意开垦土地的尝试。', 'deliberate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deliberate-2', 'deliberate', 'The committee will deliberate for several weeks before making its decision.', '委员会将仔细考虑几周,然后作出决定。', 'deliberate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('utterly-1', 'utterly', 'The village was utterly destroyed by the eruption of the volcano.', '这个村庄被火山喷发完全摧毁了。', 'utterly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('devastating-1', 'devastating', 'The storm had a devastating effect on the island''s fishing industry.', '这场风暴对岛上的渔业造成了毁灭性的影响。', 'devastating');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consecutive-1', 'consecutive', 'The region has experienced drought for five consecutive years.', '该地区已经连续五年遭遇干旱。', 'consecutive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orthodox-1', 'orthodox', 'His ideas went against the orthodox view of how the disease spread.', '他的想法与这种疾病传播方式的正统观点相悖。', 'orthodox');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thorough-1', 'thorough', 'A thorough examination of the site revealed several unusual objects.', '对现场的彻底检查发现了几件不寻常的物品。', 'thorough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('formidable-1', 'formidable', 'Crossing the desert on foot was a formidable challenge for the early explorers.', '徒步穿越沙漠对早期探险家来说是一项艰巨的挑战。', 'formidable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grim-1', 'grim', 'The report presents a grim picture of the future of the coral reefs.', '报告描绘了珊瑚礁未来的严峻前景。', 'grim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vigorous-1', 'vigorous', 'Thirty minutes of vigorous exercise a day can greatly reduce the risk of illness.', '每天三十分钟的高强度运动可以大大降低患病风险。', 'vigorous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eternal-1', 'eternal', 'Many ancient cultures believed in the eternal life of the soul.', '许多古代文化相信灵魂永恒不灭。', 'eternal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('absurd-1', 'absurd', 'The idea of flying machines once seemed absurd to most people.', '飞行器的想法曾让大多数人觉得荒谬。', 'absurd');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('destructive-1', 'destructive', 'Floods can be highly destructive in areas where trees have been removed.', '在树木被砍伐的地区,洪水的破坏性可能很大。', 'destructive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supplementary-1', 'supplementary', 'Supplementary classes were offered to children who had fallen behind.', '学校为落后的孩子提供了补充课程。', 'Supplementary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('credible-1', 'credible', 'There is no credible evidence that the ancient city ever existed.', '没有可信的证据表明这座古城曾经存在。', 'credible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wary-1', 'wary', 'Wild animals are usually wary of humans and keep their distance.', '野生动物通常对人类很警惕,并保持距离。', 'wary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notorious-1', 'notorious', 'This stretch of coast is notorious for its dangerous rocks and strong currents.', '这段海岸因危险的礁石和湍急的水流而臭名昭著。', 'notorious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('doubtless-1', 'doubtless', 'The new museum will doubtless attract a large number of tourists.', '新博物馆无疑将吸引大量游客。', 'doubtless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solitary-1', 'solitary', 'Unlike lions, most other big cats lead a solitary life.', '与狮子不同,大多数其他大型猫科动物独自生活。', 'solitary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outrageous-1', 'outrageous', 'Local people thought the price charged for water was outrageous.', '当地人认为水价高得令人愤慨。', 'outrageous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('provisional-1', 'provisional', 'These figures are provisional and may be changed when more data arrives.', '这些数字是临时的,更多数据到来后可能会更改。', 'provisional');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foremost-1', 'foremost', 'She became one of the foremost experts on ancient languages in Europe.', '她成为欧洲最重要的古代语言专家之一。', 'foremost');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('petty-1', 'petty', 'Most of the crimes in the town were petty thefts of food.', '镇上的大多数犯罪都是偷窃食物这样的小事。', 'petty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imminent-1', 'imminent', 'Local people had no warning that the eruption was imminent.', '当地人事先没有得到火山即将喷发的警告。', 'imminent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('robust-1', 'robust', 'The study was robust, with a large sample and careful controls.', '这项研究十分稳健,样本量大,对照也很严谨。', 'robust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prestigious-1', 'prestigious', 'She won a place at one of the country''s most prestigious universities.', '她考上了全国最有声望的大学之一。', 'prestigious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('superficial-1', 'superficial', 'The similarities between the two species are only superficial.', '这两个物种之间的相似之处只是表面的。', 'superficial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conspicuous-1', 'conspicuous', 'Male birds often have conspicuous colours that attract females.', '雄鸟通常有吸引雌鸟的显眼颜色。', 'conspicuous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abnormal-1', 'abnormal', 'Blood tests showed abnormal levels of iron in some of the workers.', '血液检查显示,部分工人体内铁含量异常。', 'abnormal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volatile-1', 'volatile', 'Food prices can be volatile when harvests vary greatly from year to year.', '当每年收成差异很大时,粮价可能波动剧烈。', 'volatile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volatile-2', 'volatile', 'Volatile chemicals quickly turn into gas at room temperature.', '易挥发的化学物质在室温下很快变成气体。', 'Volatile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dubious-1', 'dubious', 'The company''s claims about the health benefits of its tea are dubious.', '该公司关于其茶叶健康益处的说法很可疑。', 'dubious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drastic-1', 'drastic', 'The drought forced the government to take drastic action to save water.', '干旱迫使政府采取严厉措施节约用水。', 'drastic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('renowned-1', 'renowned', 'The region is renowned for the quality of its olive oil.', '这一地区以优质橄榄油著称。', 'renowned');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('uneven-1', 'uneven', 'The uneven distribution of rainfall makes farming difficult in some areas.', '降雨分布不均使一些地区难以耕作。', 'uneven');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('irregular-1', 'irregular', 'The stars in this group vary in brightness at irregular intervals.', '这组恒星的亮度以不规则的间隔变化。', 'irregular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coarse-1', 'coarse', 'The cloth was made from coarse wool and was worn by farm workers.', '这种布是用粗羊毛织成的,供农场工人穿着。', 'coarse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relentless-1', 'relentless', 'The relentless growth of the city has swallowed up nearby villages.', '城市持续不断的扩张吞并了附近的村庄。', 'relentless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blunt-1', 'blunt', 'Early stone tools were often blunt and had to be sharpened regularly.', '早期的石器常常很钝,需要定期打磨。', 'blunt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tangible-1', 'tangible', 'The programme has brought tangible benefits to people in the poorest areas.', '这个项目给最贫困地区的人们带来了切实的好处。', 'tangible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intricate-1', 'intricate', 'The temple walls are covered with intricate carvings of animals and plants.', '寺庙的墙壁上布满了精细的动植物雕刻。', 'intricate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('latent-1', 'latent', 'The virus can remain latent in the body for many years.', '这种病毒可以在体内潜伏多年。', 'latent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tentative-1', 'tentative', 'The team reached a tentative conclusion, which will need further testing.', '研究团队得出了一个初步结论,还需要进一步检验。', 'tentative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pointless-1', 'pointless', 'Many workers felt that the new rules were pointless and a waste of time.', '许多工人觉得新规定毫无意义,纯属浪费时间。', 'pointless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('savage-1', 'savage', 'The early settlers wrongly described the local people as savage.', '早期定居者错误地把当地人描述为野蛮的。', 'savage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gigantic-1', 'gigantic', 'Gigantic waves struck the coast after the undersea earthquake.', '海底地震后,巨浪袭击了海岸。', 'Gigantic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('idle-1', 'idle', 'Much of the farm equipment lies idle for most of the year.', '大部分农业设备一年中多数时间都闲置着。', 'idle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ruthless-1', 'ruthless', 'The ruthless pursuit of profit caused great harm to the environment.', '对利润的无情追逐对环境造成了巨大危害。', 'ruthless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subordinate-1', 'subordinate', 'In the old system, the needs of workers were subordinate to those of owners.', '在旧制度下,工人的需求次于所有者的需求。', 'subordinate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subordinate-2', 'subordinate', 'A good manager listens carefully to the ideas of each subordinate.', '好的管理者会认真听取每位下属的想法。', 'subordinate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interim-1', 'interim', 'An interim report will be published before the end of the project.', '项目结束前将发布一份中期报告。', 'interim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neighbouring-1', 'neighbouring', 'People from neighbouring villages came to trade at the weekly market.', '邻近村庄的人来每周一次的集市上做买卖。', 'neighbouring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mighty-1', 'mighty', 'The mighty river once carried goods far into the centre of the continent.', '这条大河曾把货物运到大陆腹地。', 'mighty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unfair-1', 'unfair', 'Many people felt that the new tax was unfair to the poor.', '许多人觉得新税对穷人不公平。', 'unfair');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acquire-1', 'acquire', 'Young children acquire language without any formal teaching.', '幼儿不需要正规教学就能习得语言。', 'acquire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obtain-1', 'obtain', 'Researchers obtained the data from hospitals in three different countries.', '研究者从三个不同国家的医院获得了这些数据。', 'obtained');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('achieve-1', 'achieve', 'The country hopes to achieve its target of zero emissions by 2050.', '这个国家希望到 2050 年实现零排放目标。', 'achieve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attain-1', 'attain', 'Few birds of this species attain full adult size before their second year.', '这种鸟大多要到第二年以后才能长到成年体型。', 'attain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accomplish-1', 'accomplish', 'The team accomplished the task with very limited equipment and funding.', '团队在设备和资金都很有限的情况下完成了任务。', 'accomplished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adapt-1', 'adapt', 'Many species adapt quickly to changes in temperature.', '许多物种能很快适应温度变化。', 'adapt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adapt-2', 'adapt', 'The novel was adapted for television and watched by millions of people.', '这部小说被改编成电视剧,有数百万人观看。', 'adapted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adjust-1', 'adjust', 'It takes the eyes several minutes to adjust to the dark.', '眼睛需要几分钟才能适应黑暗。', 'adjust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('modify-1', 'modify', 'Scientists have modified the crop so that it needs less water.', '科学家对这种作物进行了改良,使它需要的水更少。', 'modified');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alter-1', 'alter', 'Human activity has greatly altered the shape of the coastline.', '人类活动极大地改变了海岸线的形状。', 'altered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enhance-1', 'enhance', 'Good lighting can enhance the appearance of a museum''s collection.', '良好的照明能提升博物馆藏品的观感。', 'enhance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('improve-1', 'improve', 'Planting trees can improve air quality in crowded city centres.', '植树可以改善拥挤市中心的空气质量。', 'improve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boost-1', 'boost', 'Tourism has helped to boost the local economy in recent years.', '近年来,旅游业推动了当地经济的发展。', 'boost');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boost-2', 'boost', 'The new railway gave a major boost to trade between the two cities.', '新铁路大大推动了两座城市之间的贸易。', 'boost');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('promote-1', 'promote', 'Regular walking can promote better sleep and a healthier heart.', '经常散步可以促进睡眠,让心脏更健康。', 'promote');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('promote-2', 'promote', 'She was promoted to head of the department after only three years.', '仅仅三年后,她就被提拔为部门负责人。', 'promoted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('facilitate-1', 'facilitate', 'The new canal facilitated the movement of goods between the two regions.', '新运河使两个地区之间的货物运输更加便利。', 'facilitated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foster-1', 'foster', 'Group projects can foster cooperation and communication among students.', '小组项目可以培养学生的合作和沟通能力。', 'foster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cultivate-1', 'cultivate', 'Schools should cultivate curiosity as well as teach basic skills.', '学校既要传授基本技能,也要培养好奇心。', 'cultivate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cultivate-2', 'cultivate', 'Local farmers cultivate rice on narrow steps cut into the hillside.', '当地农民在山坡上开凿的狭窄梯田里种植水稻。', 'cultivate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nurture-1', 'nurture', 'Good teachers nurture the natural abilities of every child in the class.', '好老师会培育班上每个孩子的天赋。', 'nurture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stimulate-1', 'stimulate', 'Lower taxes may stimulate investment in small businesses.', '减税可能刺激对小企业的投资。', 'stimulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('motivate-1', 'motivate', 'Praise can motivate students more effectively than the threat of punishment.', '表扬比惩罚的威胁更能有效地激励学生。', 'motivate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('encourage-1', 'encourage', 'Cheap public transport may encourage people to leave their cars at home.', '便宜的公共交通可能鼓励人们不开车出行。', 'encourage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inhibit-1', 'inhibit', 'Certain chemicals in the leaves inhibit the growth of nearby plants.', '叶子中的某些化学物质会抑制附近植物的生长。', 'inhibit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hinder-1', 'hinder', 'Poor roads continue to hinder the development of the region''s economy.', '糟糕的道路继续阻碍该地区的经济发展。', 'hinder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impede-1', 'impede', 'Fallen trees can impede the flow of water along the river.', '倒下的树木可能妨碍河水流动。', 'impede');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hamper-1', 'hamper', 'Bad weather hampered efforts to rescue the crew of the ship.', '恶劣天气妨碍了营救船员的工作。', 'hampered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('restrict-1', 'restrict', 'The new rules restrict the number of boats allowed on the lake.', '新规定限制了湖上允许通行的船只数量。', 'restrict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('constrain-1', 'constrain', 'A lack of funding has constrained research in this field for many years.', '多年来,资金短缺一直制约着这一领域的研究。', 'constrained');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('limit-1', 'limit', 'Many cities now limit the use of cars in their historic centres.', '现在许多城市限制在历史城区使用汽车。', 'limit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('limit-2', 'limit', 'There is a limit to how much information the brain can process.', '大脑能处理的信息量是有限度的。', 'limit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prohibit-1', 'prohibit', 'The law prohibits the sale of these birds and their eggs.', '法律禁止出售这些鸟及其蛋。', 'prohibits');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ban-1', 'ban', 'Several countries have banned the use of this pesticide on farms.', '几个国家已经禁止在农场使用这种农药。', 'banned');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ban-2', 'ban', 'A ban on hunting has allowed the number of whales to recover.', '禁猎令使鲸鱼的数量得以恢复。', 'ban');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prevent-1', 'prevent', 'Washing hands regularly helps to prevent the spread of infection.', '经常洗手有助于防止感染传播。', 'prevent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('avoid-1', 'avoid', 'Some animals move only at night to avoid the heat of the sun.', '有些动物只在夜间活动,以避开太阳的炎热。', 'avoid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eliminate-1', 'eliminate', 'Better design could eliminate most of the waste from the production process.', '更好的设计可以消除生产过程中的大部分浪费。', 'eliminate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eradicate-1', 'eradicate', 'A global vaccination programme helped to eradicate smallpox in the 1970s.', '全球疫苗接种计划帮助在 20 世纪 70 年代根除了天花。', 'eradicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reduce-1', 'reduce', 'Insulating older homes could greatly reduce the amount of energy they use.', '给老房子加装隔热层可以大大减少能源消耗。', 'reduce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('minimise-1', 'minimise', 'Engineers tried to minimise the effect of the dam on local wildlife.', '工程师努力把大坝对当地野生动物的影响降到最低。', 'minimise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maximise-1', 'maximise', 'Farmers plant crops in rows to maximise the amount of sunlight they get.', '农民成行种植作物,以最大限度地获得阳光。', 'maximise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mitigate-1', 'mitigate', 'Planting trees along rivers can mitigate the effects of flooding.', '沿河植树可以减轻洪水的影响。', 'mitigate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alleviate-1', 'alleviate', 'The new medicine can alleviate pain without causing drowsiness.', '这种新药可以缓解疼痛,而且不会让人犯困。', 'alleviate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relieve-1', 'relieve', 'Additional bus services were introduced to relieve pressure on the railway.', '增设公交线路是为了缓解铁路的压力。', 'relieve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tackle-1', 'tackle', 'Governments must work together to tackle the problem of plastic waste.', '各国政府必须共同努力,解决塑料垃圾问题。', 'tackle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('address-1', 'address', 'The report fails to address the causes of poverty in rural areas.', '这份报告未能处理农村贫困的根源。', 'address');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cope-with-1', 'cope-with', 'Older cities were not designed to cope with so many cars.', '老城市在设计时并没有考虑如何应对这么多汽车。', 'cope with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deal-with-1', 'deal-with', 'Some schools have trained staff to deal with students'' mental health problems.', '一些学校培训了教职工来处理学生的心理健康问题。', 'deal with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resolve-1', 'resolve', 'Scientists hope the new data will resolve the long debate about the fossils.', '科学家希望新数据能解决关于这些化石的长期争论。', 'resolve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('implement-1', 'implement', 'The government plans to implement the new policy over the next five years.', '政府计划在未来五年内实施这项新政策。', 'implement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('execute-1', 'execute', 'Robots can execute the same task thousands of times without making an error.', '机器人能够数千次执行同一任务而不出差错。', 'execute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('execute-2', 'execute', 'The rebel leaders were captured and executed by order of the king.', '叛军领袖被捕后,由国王下令处决。', 'executed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conduct-1', 'conduct', 'The team conducted a survey of over two thousand households.', '研究团队对两千多户家庭进行了调查。', 'conducted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('undertake-1', 'undertake', 'The museum has undertaken a major study of its early collections.', '博物馆对其早期藏品开展了一项大型研究。', 'undertaken');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pursue-1', 'pursue', 'More women are now choosing to pursue careers in engineering.', '现在越来越多的女性选择从事工程类职业。', 'pursue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('establish-1', 'establish', 'The first European settlers established a small colony on the coast.', '最早的欧洲定居者在海岸建立了一个小殖民地。', 'established');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('found-1', 'found', 'The university was founded in the nineteenth century by a group of local merchants.', '这所大学由一群当地商人创立于十九世纪。', 'founded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('initiate-1', 'initiate', 'The government initiated a programme to bring clean water to rural areas.', '政府发起了一项计划,为农村地区提供清洁用水。', 'initiated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('launch-1', 'launch', 'The agency plans to launch a new satellite to study the oceans.', '该机构计划发射一颗新卫星来研究海洋。', 'launch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('launch-2', 'launch', 'The launch of the campaign attracted wide attention from the national press.', '这项运动的启动引起了全国媒体的广泛关注。', 'launch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emerge-1', 'emerge', 'New forms of writing emerged as trade spread across the region.', '随着贸易在该地区的扩展,新的文字形式出现了。', 'emerged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arise-1', 'arise', 'Problems can arise when a new species is brought into an area.', '把新物种引入某个地区时可能出现问题。', 'arise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('occur-1', 'occur', 'Most earthquakes occur along the edges of the Earth''s major plates.', '大多数地震发生在地球主要板块的边缘。', 'occur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evolve-1', 'evolve', 'Birds are thought to have evolved from small meat-eating dinosaurs.', '人们认为鸟类是从小型食肉恐龙进化而来的。', 'evolved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('develop-1', 'develop', 'Children develop their reading skills at different speeds.', '孩子们阅读能力的发展速度各不相同。', 'develop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accumulate-1', 'accumulate', 'Harmful chemicals can accumulate in the bodies of large fish.', '有害化学物质可能在大型鱼类体内积累。', 'accumulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sustain-1', 'sustain', 'The land could no longer sustain such a large population.', '这片土地再也无法维持这么多人口。', 'sustain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retain-1', 'retain', 'Clay soils retain water far better than sandy ones.', '黏土的保水能力远远强于沙土。', 'retain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preserve-1', 'preserve', 'The cold, dry air of the cave helped to preserve the paintings.', '洞穴寒冷干燥的空气有助于保存这些壁画。', 'preserve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conserve-1', 'conserve', 'Many desert plants have small leaves in order to conserve water.', '许多沙漠植物的叶子很小,以节约水分。', 'conserve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('protect-1', 'protect', 'Thick fur protects the animal from the extreme cold of the Arctic.', '厚厚的皮毛保护这种动物免受北极的严寒。', 'protects');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ensure-1', 'ensure', 'Regular inspections ensure that the water remains safe to drink.', '定期检查确保水质仍可安全饮用。', 'ensure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secure-1', 'secure', 'The company secured funding to develop its new battery technology.', '该公司获得了资金,用于开发新电池技术。', 'secured');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secure-2', 'secure', 'Most people want a secure job that offers a regular income.', '大多数人都想要一份收入稳定的安稳工作。', 'secure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acknowledge-1', 'acknowledge', 'The author acknowledges that the sample used in the study was small.', '作者承认这项研究使用的样本量很小。', 'acknowledges');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recognise-1', 'recognise', 'Her work was not recognised until many years after her death.', '她的成果直到她去世多年后才得到认可。', 'recognised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perceive-1', 'perceive', 'Humans perceive colour through special cells at the back of the eye.', '人类通过眼睛后部的特殊细胞感知颜色。', 'perceive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regard-1', 'regard', 'Many historians regard this as the most important battle of the war.', '许多历史学家把这场战役看作这场战争中最重要的一场。', 'regard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consider-1', 'consider', 'Planners must consider the needs of older residents when designing new towns.', '规划者在设计新城镇时必须考虑老年居民的需求。', 'consider');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('specify-1', 'specify', 'The rules specify how much waste each factory may release.', '规定具体说明了每家工厂可以排放多少废物。', 'specify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clarify-1', 'clarify', 'Further tests are needed to clarify the cause of the illness.', '需要进一步检查来澄清病因。', 'clarify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('summarise-1', 'summarise', 'The final chapter summarises the main findings of the research.', '最后一章总结了这项研究的主要发现。', 'summarises');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compile-1', 'compile', 'Scholars spent decades compiling the first complete dictionary of the language.', '学者们花了几十年编纂这种语言的第一部完整词典。', 'compiling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('integrate-1', 'integrate', 'The new system integrates information from several different sources.', '新系统整合了来自多个不同来源的信息。', 'integrates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incorporate-1', 'incorporate', 'Modern buildings often incorporate features that reduce their use of energy.', '现代建筑常常融入一些减少能耗的设计。', 'incorporate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('combine-1', 'combine', 'Tin and copper were combined to produce a much harder metal.', '锡和铜结合后产生了一种硬度高得多的金属。', 'combined');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('merge-1', 'merge', 'Two small colleges merged to form the new university in 1965.', '两所小学院于 1965 年合并,组成了这所新大学。', 'merged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('separate-1', 'separate', 'The machine separates the seeds from the rest of the plant.', '这台机器把种子从植株的其他部分分离出来。', 'separates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distinguish-1', 'distinguish', 'Babies can distinguish their mother''s voice from those of other people.', '婴儿能把母亲的声音和其他人的声音区分开。', 'distinguish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('differentiate-1', 'differentiate', 'This feature helps scientists to differentiate between the two species.', '这一特征有助于科学家区分这两个物种。', 'differentiate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compare-1', 'compare', 'The study compares the health of people in rural and urban areas.', '这项研究比较了农村和城市居民的健康状况。', 'compares');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contrast-1', 'contrast', 'The author contrasts life in the village with life in the modern city.', '作者把乡村生活和现代城市生活作了对比。', 'contrasts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contrast-2', 'contrast', 'There is a sharp contrast between the wet east and the dry west.', '潮湿的东部和干燥的西部形成鲜明对比。', 'contrast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resemble-1', 'resemble', 'Some harmless insects have evolved to resemble more dangerous species.', '一些无害的昆虫进化得与更危险的物种相似。', 'resemble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coincide-1', 'coincide', 'The arrival of the birds coincides with the appearance of certain insects.', '这些鸟到来的时间恰好与某些昆虫出现的时间相同。', 'coincides');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correspond-1', 'correspond', 'The dates in the diary correspond closely with those in official records.', '日记中的日期与官方记录基本相符。', 'correspond');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depend-on-1', 'depend-on', 'The health of the forest will depend on the amount of rain it receives.', '森林的健康将取决于它获得的雨量。', 'depend on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rely-on-1', 'rely-on', 'Many small islands rely on tourism for most of their income.', '许多小岛的大部分收入依赖旅游业。', 'rely on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('involve-1', 'involve', 'Learning to read involves several different areas of the brain.', '学习阅读涉及大脑的多个不同区域。', 'involves');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entail-1', 'entail', 'Moving the whole village would entail enormous cost and disruption.', '搬迁整个村庄必然涉及巨大的成本和混乱。', 'entail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('require-1', 'require', 'Most tropical plants require high levels of light and water.', '大多数热带植物需要充足的光照和水分。', 'require');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('demand-1', 'demand', 'Local residents demanded better protection from the floods.', '当地居民要求加强防洪保护。', 'demanded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('demand-2', 'demand', 'Demand for electricity is highest in the early evening.', '傍晚时分的电力需求最高。', 'Demand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exploit-1', 'exploit', 'Companies have begun to exploit the mineral resources under the ice.', '公司已开始开发冰层下的矿产资源。', 'exploit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exploit-2', 'exploit', 'Factory owners were accused of exploiting young workers in the nineteenth century.', '十九世纪的工厂主被指控剥削年轻工人。', 'exploiting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('utilise-1', 'utilise', 'Solar panels utilise energy from the sun to produce electricity.', '太阳能电池板利用太阳的能量发电。', 'utilise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('employ-1', 'employ', 'The factory once employed more than half of the people in the town.', '这家工厂曾雇用镇上一半以上的人。', 'employed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('employ-2', 'employ', 'The researchers employed a new method to measure the age of the rocks.', '研究者使用了一种新方法测定岩石的年龄。', 'employed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apply-1', 'apply', 'The same principle can be applied to the design of aircraft wings.', '同样的原理可以应用于飞机机翼的设计。', 'applied');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apply-2', 'apply', 'Farmers can apply for government grants to plant new forests.', '农民可以申请政府补助来种植新的森林。', 'apply');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distribute-1', 'distribute', 'The charity distributes food to families in the areas worst affected.', '这家慈善机构向受灾最严重地区的家庭分发食物。', 'distributes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assign-1', 'assign', 'Participants were asked to assign a score to each of the images.', '参与者被要求给每张图片打分。', 'assign');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delegate-1', 'delegate', 'Good managers delegate routine tasks so they can focus on planning.', '优秀的管理者会把日常工作委派出去,以便专注于规划。', 'delegate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delegate-2', 'delegate', 'Each country sent a delegate to the conference on climate change.', '每个国家都派了一名代表参加气候变化会议。', 'delegate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monitor-1', 'monitor', 'Satellites are used to monitor changes in the size of the ice sheets.', '卫星被用来监控冰盖面积的变化。', 'monitor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regulate-1', 'regulate', 'The skin helps to regulate the temperature of the body.', '皮肤有助于调节体温。', 'regulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supervise-1', 'supervise', 'Experienced staff supervise the students during their first year of training.', '培训的第一年,由有经验的员工监督学生。', 'supervise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inspect-1', 'inspect', 'Officials inspect the factory twice a year to check the air quality.', '官员每年两次检查工厂的空气质量。', 'inspect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detect-1', 'detect', 'Some sharks can detect a tiny amount of blood in the water.', '有些鲨鱼能在水中检测到极少量的血液。', 'detect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discover-1', 'discover', 'Marie Curie discovered two new elements during her research in Paris.', '玛丽·居里在巴黎进行研究时发现了两种新元素。', 'discovered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invent-1', 'invent', 'No one knows exactly who invented the first wheel.', '没有人确切知道最早的轮子是谁发明的。', 'invented');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('devise-1', 'devise', 'Engineers have devised a way of removing salt from seawater more cheaply.', '工程师想出了一种更便宜的海水淡化方法。', 'devised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('design-1', 'design', 'The building was designed to use as little energy as possible.', '这座建筑的设计目的是尽量少用能源。', 'designed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('formulate-1', 'formulate', 'Scientists formulate a hypothesis before they begin an experiment.', '科学家在开始实验前先提出假设。', 'formulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revise-1', 'revise', 'Scientists had to revise their estimates after the new data arrived.', '新数据到来后,科学家不得不修订他们的估算。', 'revise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('update-1', 'update', 'The database is updated every week with information from local hospitals.', '数据库每周根据当地医院的信息更新一次。', 'updated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abandon-1', 'abandon', 'Many farmers were forced to abandon their land during the long drought.', '在长期干旱期间,许多农民被迫放弃土地。', 'abandon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neglect-1', 'neglect', 'For many years, governments tended to neglect the needs of rural areas.', '多年来,政府往往忽视农村地区的需求。', 'neglect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ignore-1', 'ignore', 'Early reports of the disease were largely ignored by the authorities.', '关于这种疾病的早期报告大多被当局忽略了。', 'ignored');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overlook-1', 'overlook', 'Researchers often overlook the role that women played in early farming.', '研究者常常忽视女性在早期农业中的作用。', 'overlook');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overlook-2', 'overlook', 'The ancient fort overlooks the river from the top of a steep hill.', '这座古堡位于陡峭的山顶,俯瞰着河流。', 'overlooks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('underestimate-1', 'underestimate', 'People often underestimate how long it takes to form a new habit.', '人们常常低估养成新习惯所需的时间。', 'underestimate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overestimate-1', 'overestimate', 'Drivers tend to overestimate their own ability behind the wheel.', '司机往往高估自己的驾驶能力。', 'overestimate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exaggerate-1', 'exaggerate', 'Newspapers sometimes exaggerate the risks of new technology to attract readers.', '报纸有时夸大新技术的风险来吸引读者。', 'exaggerate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anticipate-1', 'anticipate', 'Few experts anticipated how quickly the internet would change society.', '很少有专家预料到互联网会如此迅速地改变社会。', 'anticipated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foresee-1', 'foresee', 'It is impossible to foresee all the effects of a new technology.', '不可能预见一项新技术的所有影响。', 'foresee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confront-1', 'confront', 'Coastal cities must now confront the problem of rising sea levels.', '沿海城市现在必须面对海平面上升的问题。', 'confront');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('encounter-1', 'encounter', 'Early explorers encountered many animals that they had never seen before.', '早期探险家遇到了许多从未见过的动物。', 'encountered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('undergo-1', 'undergo', 'Caterpillars undergo a complete change of form as they become butterflies.', '毛毛虫在变成蝴蝶的过程中要经历完全的形态变化。', 'undergo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endure-1', 'endure', 'Workers on the railway had to endure extreme heat and disease.', '铁路工人不得不忍受酷热和疾病。', 'endure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('withstand-1', 'withstand', 'The new buildings are designed to withstand strong earthquakes.', '新建筑的设计能够承受强烈地震。', 'withstand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resist-1', 'resist', 'Some crops have been bred to resist common insects and diseases.', '一些作物经过培育,能够抵抗常见的虫害和疾病。', 'resist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tolerate-1', 'tolerate', 'Few fish can tolerate such high levels of salt in the water.', '很少有鱼能忍受水中这么高的盐度。', 'tolerate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compensate-1', 'compensate', 'Blind people may develop better hearing to compensate for their loss of sight.', '盲人的听力可能会变得更好,以弥补视力的丧失。', 'compensate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contribute-1', 'contribute', 'Local people contributed money and labour to build the new school.', '当地人为建造新学校贡献了资金和劳力。', 'contributed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('participate-1', 'participate', 'More than two thousand volunteers agreed to participate in the study.', '两千多名志愿者同意参与这项研究。', 'participate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cooperate-1', 'cooperate', 'Wolves cooperate with each other when hunting large animals.', '狼在捕猎大型动物时互相合作。', 'cooperate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collaborate-1', 'collaborate', 'Scientists from twelve countries collaborated on the project.', '来自十二个国家的科学家在这个项目上开展了协作。', 'collaborated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interact-1', 'interact', 'Babies learn language by interacting with the people around them.', '婴儿通过与周围的人互动来学习语言。', 'interacting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('communicate-1', 'communicate', 'Elephants communicate over long distances using very low sounds.', '大象利用极低的声音进行远距离交流。', 'communicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('negotiate-1', 'negotiate', 'The two countries negotiated a treaty to share water from the river.', '两国通过谈判达成了一项共享河水的条约。', 'negotiated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('advocate-1', 'advocate', 'Many doctors advocate a diet rich in vegetables and whole grains.', '许多医生提倡多吃蔬菜和全谷物的饮食。', 'advocate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('advocate-2', 'advocate', 'She was a strong advocate of equal education for girls.', '她是女孩平等受教育的坚定提倡者。', 'advocate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oppose-1', 'oppose', 'Local farmers strongly oppose the plan to build an airport on their land.', '当地农民强烈反对在他们的土地上建机场的计划。', 'oppose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('object-to-doing-sth-1', 'object-to-doing-sth', 'Many residents object to paying higher taxes for the new stadium.', '许多居民反对为新体育场缴纳更高的税。', 'object to');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('favour-1', 'favour', 'Most of the experts favour a gradual approach to changing the system.', '大多数专家支持逐步改革这一体系。', 'favour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('justify-1', 'justify', 'The results do not justify the high cost of the treatment.', '这样的结果不足以证明高昂的治疗费用是合理的。', 'justify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convince-1', 'convince', 'It took years to convince other scientists that the theory was correct.', '花了多年时间才让其他科学家相信这一理论是正确的。', 'convince');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('persuade-1', 'persuade', 'Campaigns have failed to persuade many young people to stop smoking.', '宣传活动未能说服许多年轻人戒烟。', 'persuade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elevate-1', 'elevate', 'Stress can elevate blood pressure and increase the risk of heart disease.', '压力会使血压升高,增加患心脏病的风险。', 'elevate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exert-1', 'exert', 'Climate exerts a strong influence on where early farming communities developed.', '早期农耕社群在哪里发展起来,很大程度上受气候影响。', 'exerts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expedite-1', 'expedite', 'New software has helped to expedite the process of checking medical records.', '新软件加快了核对病历的流程。', 'expedite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('originate-1', 'originate', 'The custom is thought to originate from an ancient harvest festival.', '这一习俗被认为起源于一个古老的丰收节。', 'originate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disclose-1', 'disclose', 'Companies are now required to disclose how much carbon they produce.', '现在公司被要求披露自己的碳排放量。', 'disclose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distort-1', 'distort', 'The curved surface of the Earth tends to distort flat maps.', '地球的曲面往往会使平面地图变形。', 'distort');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imitate-1', 'imitate', 'Young birds learn to sing by imitating the songs of adult males.', '幼鸟通过模仿成年雄鸟的歌声来学习鸣叫。', 'imitating');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dominate-1', 'dominate', 'A few large companies now dominate the global market for seeds.', '现在少数几家大公司主导着全球种子市场。', 'dominate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('popularise-1', 'popularise', 'Television programmes helped to popularise science among ordinary people.', '电视节目帮助在普通人中普及科学。', 'popularise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convey-1', 'convey', 'Facial expressions can convey emotions that words cannot express.', '面部表情可以传达言语无法表达的情感。', 'convey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convey-2', 'convey', 'Long stone channels were built to convey water to the city.', '人们修建了长长的石渠,把水运送到城市。', 'convey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deserve-1', 'deserve', 'Many believe that the scientist deserves more credit for this discovery.', '许多人认为,这位科学家应该因这一发现得到更多赞誉。', 'deserves');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affirm-1', 'affirm', 'The results of the study affirm the value of early education.', '这项研究的结果肯定了早期教育的价值。', 'affirm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assure-1', 'assure', 'The authorities assured residents that the water was safe to drink.', '当局向居民保证,这些水可以安全饮用。', 'assured');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('substantiate-1', 'substantiate', 'There is little data to substantiate the claims made by the company.', '几乎没有数据能证实该公司的说法。', 'substantiate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stipulate-1', 'stipulate', 'The agreement stipulates that the land must be used only for farming.', '协议规定,这片土地只能用于耕作。', 'stipulates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('observe-1', 'observe', 'Researchers observed the behaviour of the monkeys for over ten years.', '研究者观察这些猴子的行为长达十多年。', 'observed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('observe-2', 'observe', 'All ships must observe the rules that protect the marine park.', '所有船只都必须遵守保护海洋公园的规定。', 'observe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abide-by-1', 'abide-by', 'Member countries agreed to abide by the rules set out in the treaty.', '成员国同意遵守条约中规定的规则。', 'abide by');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consume-1', 'consume', 'Large data centres consume enormous amounts of electricity every year.', '大型数据中心每年消耗大量电力。', 'consume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consolidate-1', 'consolidate', 'Sleep appears to consolidate new memories formed during the day.', '睡眠似乎能巩固白天形成的新记忆。', 'consolidate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ascend-1', 'ascend', 'Warm air ascends and cools as it moves higher above the ground.', '暖空气上升,离地面越高温度越低。', 'ascends');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instil-1', 'instil', 'Parents can instil good reading habits in children from an early age.', '父母可以从小给孩子灌输良好的阅读习惯。', 'instil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enlighten-1', 'enlighten', 'Public lectures were intended to enlighten ordinary people about recent discoveries.', '公开讲座旨在向普通人介绍最新发现,启发他们。', 'enlighten');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transpire-1', 'transpire', 'It later transpired that the data had been recorded incorrectly.', '后来得知,这些数据记录有误。', 'transpired');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transpire-2', 'transpire', 'Plants transpire more water on hot and windy days.', '植物在炎热多风的日子里蒸腾的水分更多。', 'transpire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reinforce-1', 'reinforce', 'Repeating information at intervals helps to reinforce it in the memory.', '间隔重复信息有助于加深记忆。', 'reinforce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confine-1', 'confine', 'The disease was confined to a small area in the south of the country.', '这种疾病被限制在该国南部的一小片地区。', 'confined');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depict-1', 'depict', 'The paintings depict scenes from everyday life in ancient Rome.', '这些画描绘了古罗马日常生活的场景。', 'depict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('render-1', 'render', 'Heavy flooding rendered the main road impossible to use.', '严重的洪水使主干道无法通行。', 'rendered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('undermine-1', 'undermine', 'Rising costs could undermine the success of the entire programme.', '不断上升的成本可能削弱整个项目的成效。', 'undermine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scatter-1', 'scatter', 'Birds help to scatter the seeds of many forest plants.', '鸟类帮助散布许多森林植物的种子。', 'scatter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interfere-1', 'interfere', 'Bright lights can interfere with the sleep patterns of city residents.', '明亮的灯光可能妨碍城市居民的睡眠规律。', 'interfere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grasp-1', 'grasp', 'Young children often find it hard to grasp the idea of time.', '幼儿常常很难理解时间的概念。', 'grasp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manipulate-1', 'manipulate', 'Octopuses can manipulate objects with great skill using their long arms.', '章鱼能用长长的腕灵巧地操纵物体。', 'manipulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('activate-1', 'activate', 'The sensor will activate the alarm if the water level rises too high.', '水位过高时,传感器会启动警报。', 'activate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elaborate-1', 'elaborate', 'The author does not elaborate on how the data was collected.', '作者没有详细阐述数据是如何收集的。', 'elaborate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elaborate-2', 'elaborate', 'The male bird builds an elaborate nest to attract a female.', '雄鸟筑起精致的巢来吸引雌鸟。', 'elaborate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coordinate-1', 'coordinate', 'A central office coordinates the work of all the local health teams.', '中央办公室协调各地卫生团队的工作。', 'coordinates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overlap-1', 'overlap', 'The ranges of the two species overlap in the north of the country.', '这两个物种的分布范围在该国北部重叠。', 'overlap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('simplify-1', 'simplify', 'The new form was designed to simplify the process of applying for aid.', '新表格的设计是为了简化申请援助的流程。', 'simplify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('standardise-1', 'standardise', 'The government tried to standardise the spelling of the national language.', '政府试图统一这种国语的拼写。', 'standardise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vary-1', 'vary', 'Average temperatures vary greatly from one part of the country to another.', '全国各地的平均气温差异很大。', 'vary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('declare-1', 'declare', 'The government declared a national emergency after the earthquake.', '地震后,政府宣布全国进入紧急状态。', 'declared');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capture-1', 'capture', 'Cameras in the forest captured images of the rare animal at night.', '森林里的相机在夜间捕捉到了这种珍稀动物的影像。', 'captured');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rely-1', 'rely', 'Many of these communities rely heavily on fishing for their food.', '这些社区中有许多在食物上严重依赖捕鱼。', 'rely');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('derive-1', 'derive', 'Plants derive most of their energy from sunlight.', '植物的大部分能量来自阳光。', 'derive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bind-1', 'bind', 'The treaty will bind all member countries to reducing their carbon emissions.', '这项条约将约束所有成员国减少碳排放。', 'bind');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('permit-1', 'permit', 'Local laws do not permit building within a hundred metres of the shore.', '当地法律不允许在距海岸一百米以内建房。', 'permit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('permit-2', 'permit', 'Visitors must obtain a permit before they enter the protected area.', '游客进入保护区前必须获得许可证。', 'permit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embrace-1', 'embrace', 'Many older workers have been quick to embrace new technology.', '许多年纪较大的员工很快就接受了新技术。', 'embrace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overcome-1', 'overcome', 'Engineers had to overcome many difficulties to build the tunnel.', '工程师必须克服许多困难才能建成这条隧道。', 'overcome');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cease-1', 'cease', 'The volcano ceased to be active about two thousand years ago.', '这座火山大约两千年前就停止了活动。', 'ceased');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strengthen-1', 'strengthen', 'Regular exercise can strengthen the bones and reduce the risk of falls.', '经常锻炼可以强健骨骼,降低跌倒的风险。', 'strengthen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consult-1', 'consult', 'Patients should consult a doctor before taking any new medicine.', '服用任何新药前,患者都应该咨询医生。', 'consult');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('devote-1', 'devote', 'She devoted her whole career to the study of African birds.', '她把整个职业生涯都投入到非洲鸟类的研究之中。', 'devoted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dedicate-1', 'dedicate', 'The institute will dedicate most of its budget to cancer research.', '该研究所将把大部分预算投入癌症研究。', 'dedicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('provoke-1', 'provoke', 'The plan to close the hospital provoked angry protests from local residents.', '关闭医院的计划引起了当地居民的愤怒抗议。', 'provoked');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assemble-1', 'assemble', 'Workers assemble the parts in a large factory near the port.', '工人在港口附近的一家大工厂组装这些零件。', 'assemble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('allege-1', 'allege', 'Critics allege that the company ignored safety warnings for many years.', '批评者声称该公司多年来无视安全警告。', 'allege');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('envisage-1', 'envisage', 'The plan envisages a network of cycle paths across the whole city.', '该计划设想在全市建立自行车道网络。', 'envisages');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concede-1', 'concede', 'Even its supporters concede that the policy has been expensive.', '连这项政策的支持者也承认它花费很大。', 'concede');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endorse-1', 'endorse', 'The national medical association has endorsed the new treatment.', '全国医学协会已经认可了这种新疗法。', 'endorsed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contemplate-1', 'contemplate', 'Few people at that time would contemplate travelling so far from home.', '当时很少有人会考虑去离家这么远的地方。', 'contemplate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diminish-1', 'diminish', 'The fear of flying tends to diminish with more experience.', '随着经验增加,对飞行的恐惧往往会减弱。', 'diminish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incur-1', 'incur', 'Countries that break the agreement may incur heavy financial penalties.', '违反协议的国家可能招致高额罚款。', 'incur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oversee-1', 'oversee', 'A small committee was set up to oversee the work of the project.', '成立了一个小型委员会来监督这个项目的工作。', 'oversee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deem-1', 'deem', 'The water in the lake was deemed unsafe for swimming.', '这个湖的水被认为不适合游泳。', 'deemed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compel-1', 'compel', 'Rising costs may compel many farmers to sell their land.', '不断上涨的成本可能迫使许多农民出售土地。', 'compel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('omit-1', 'omit', 'The early maps omit many of the smaller islands in the region.', '早期地图遗漏了该地区的许多小岛。', 'omit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('halt-1', 'halt', 'The government halted work on the dam after protests by local farmers.', '在当地农民抗议后,政府叫停了大坝工程。', 'halted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proclaim-1', 'proclaim', 'The new government was quick to proclaim the country''s independence.', '新政府很快就宣告了国家独立。', 'proclaim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suppress-1', 'suppress', 'Some medicines suppress the body''s natural response to infection.', '有些药物会抑制身体对感染的自然反应。', 'suppress');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('summon-1', 'summon', 'The king summoned his advisers to discuss the threat of invasion.', '国王召集大臣们商讨入侵的威胁。', 'summoned');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revive-1', 'revive', 'Efforts are being made to revive the language among younger speakers.', '人们正在努力让这种语言在年轻人中复兴。', 'revive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boast-1', 'boast', 'The city boasts one of the finest collections of Roman art in Europe.', '这座城市拥有欧洲最好的罗马艺术藏品之一。', 'boasts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unfold-1', 'unfold', 'Events began to unfold quickly once the new king came to power.', '新国王掌权后,事态开始迅速发展。', 'unfold');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arouse-1', 'arouse', 'The strange discovery aroused great interest among scientists around the world.', '这一奇特的发现引起了世界各地科学家的极大兴趣。', 'aroused');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thrive-1', 'thrive', 'These plants thrive in warm conditions with plenty of water.', '这些植物在温暖、水分充足的环境中茁壮成长。', 'thrive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('speculate-1', 'speculate', 'Researchers can only speculate about why the city was abandoned.', '研究者只能推测这座城市被遗弃的原因。', 'speculate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conform-1', 'conform', 'Children often feel pressure to conform to the behaviour of their friends.', '孩子们常常感到要与朋友的行为保持一致的压力。', 'conform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('divert-1', 'divert', 'Engineers built a channel to divert water away from the town.', '工程师修建了一条水渠,把水从镇上引开。', 'divert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evoke-1', 'evoke', 'Certain smells can evoke strong memories of childhood.', '某些气味能唤起强烈的童年记忆。', 'evoke');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('penetrate-1', 'penetrate', 'Very little sunlight can penetrate to the bottom of the deep ocean.', '很少有阳光能穿透到深海底部。', 'penetrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strive-1', 'strive', 'Scientists continue to strive for a better understanding of the brain.', '科学家继续努力更好地理解大脑。', 'strive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embody-1', 'embody', 'These old buildings embody the values of the people who built them.', '这些老建筑体现了建造者的价值观。', 'embody');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disrupt-1', 'disrupt', 'Even small changes in temperature can disrupt the life cycle of insects.', '即使温度的微小变化,也可能扰乱昆虫的生命周期。', 'disrupt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('uphold-1', 'uphold', 'Courts are expected to uphold the law regardless of public opinion.', '无论舆论如何,法院都应维护法律。', 'uphold');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illuminate-1', 'illuminate', 'The study helps to illuminate how memories are stored in the brain.', '这项研究有助于阐明记忆是如何储存在大脑中的。', 'illuminate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discard-1', 'discard', 'Most of the fish caught by the boats are discarded as unwanted.', '船只捕捞的大部分鱼都被当作不需要的东西丢弃了。', 'discarded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reconcile-1', 'reconcile', 'It is difficult to reconcile economic growth with protecting the environment.', '很难调和经济增长与环境保护之间的矛盾。', 'reconcile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defy-1', 'defy', 'The behaviour of these tiny particles seems to defy explanation.', '这些微小粒子的行为似乎无法解释。', 'defy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notify-1', 'notify', 'Hospitals must notify the authorities of any new cases of the disease.', '医院必须把任何新病例通知有关部门。', 'notify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('offset-1', 'offset', 'Planting trees may partly offset the carbon released by air travel.', '植树也许能部分抵消航空旅行排放的碳。', 'offset');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manifest-1', 'manifest', 'The disease may not manifest itself until many years after infection.', '这种疾病可能在感染多年后才显现出来。', 'manifest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ascertain-1', 'ascertain', 'Investigators were unable to ascertain the exact cause of the fire.', '调查人员无法查明火灾的确切原因。', 'ascertain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expel-1', 'expel', 'The lungs expel carbon dioxide from the body with each breath.', '肺每次呼吸都把二氧化碳排出体外。', 'expel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adhere-1', 'adhere', 'Many patients fail to adhere to the treatment plan given by their doctor.', '许多患者未能坚持医生给出的治疗方案。', 'adhere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('safeguard-1', 'safeguard', 'New laws were passed to safeguard the rights of workers.', '新法律的通过是为了保护工人的权利。', 'safeguard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('culminate-1', 'culminate', 'Years of protest culminated in a change in the law in 1928.', '多年的抗议最终以 1928 年法律的修改告终。', 'culminated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intensify-1', 'intensify', 'Competition for water intensified as the population of the valley grew.', '随着山谷人口增长,对水资源的争夺加剧了。', 'intensified');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enrich-1', 'enrich', 'Rotting leaves enrich the soil with valuable nutrients.', '腐烂的树叶为土壤补充了宝贵的养分。', 'enrich');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elicit-1', 'elicit', 'The researchers used pictures to elicit responses from very young children.', '研究者用图片引导幼儿作出回应。', 'elicit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transcend-1', 'transcend', 'Great music can transcend differences of language and culture.', '伟大的音乐能够超越语言和文化的差异。', 'transcend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('withhold-1', 'withhold', 'The government threatened to withhold funding from schools that broke the rules.', '政府威胁要扣留违规学校的经费。', 'withhold');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('displace-1', 'displace', 'The new dam will displace thousands of people living along the river.', '新大坝将迫使沿河的数千人离开家园。', 'displace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exacerbate-1', 'exacerbate', 'Cutting down forests can exacerbate the effects of heavy rain.', '砍伐森林会加剧暴雨的影响。', 'exacerbate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('necessitate-1', 'necessitate', 'The growth of the city will necessitate a new water supply.', '城市的发展使得新的供水系统成为必要。', 'necessitate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exemplify-1', 'exemplify', 'These gardens exemplify the Japanese love of simplicity and balance.', '这些花园是日本人崇尚简约与平衡的典型例子。', 'exemplify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impair-1', 'impair', 'Too little sleep can impair judgement as much as alcohol.', '睡眠过少对判断力的损害与酒精一样大。', 'impair');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reclaim-1', 'reclaim', 'The Dutch have reclaimed large areas of land from the sea.', '荷兰人从海中开垦了大片土地。', 'reclaimed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disregard-1', 'disregard', 'Some factories continued to disregard the rules on waste disposal.', '一些工厂继续无视废物处理的规定。', 'disregard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detach-1', 'detach', 'Part of the glacier may detach and fall into the sea.', '部分冰川可能脱离并坠入海中。', 'detach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('escalate-1', 'escalate', 'Small disagreements over water can quickly escalate into serious conflict.', '关于水的小分歧可能很快升级为严重冲突。', 'escalate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('avert-1', 'avert', 'Early action helped to avert a serious shortage of food.', '及早采取行动有助于避免严重的粮食短缺。', 'avert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bypass-1', 'bypass', 'The new road will bypass the town and reduce traffic in the centre.', '新公路将绕过小镇,减少市中心的交通流量。', 'bypass');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discern-1', 'discern', 'It is difficult to discern any pattern in such a small set of data.', '在这么小的数据集中,很难察觉出任何规律。', 'discern');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ascribe-1', 'ascribe', 'Early people often ascribed natural disasters to the anger of the gods.', '早期的人们常常把自然灾害归因于神的愤怒。', 'ascribed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heighten-1', 'heighten', 'Caffeine can heighten alertness for several hours after it is taken.', '摄入咖啡因后的几小时内,人的警觉性会提高。', 'heighten');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commend-1', 'commend', 'The report commends the school for its work with disabled children.', '报告称赞这所学校在帮助残障儿童方面所做的工作。', 'commends');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('succumb-1', 'succumb', 'Many of the settlers succumbed to disease during their first winter.', '许多定居者在第一个冬天死于疾病。', 'succumbed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intrigue-1', 'intrigue', 'The unusual shape of the bones continues to intrigue scientists.', '这些骨头不同寻常的形状一直引起科学家的兴趣。', 'intrigue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tighten-1', 'tighten', 'The government plans to tighten controls on the use of plastic bags.', '政府计划加强对塑料袋使用的管制。', 'tighten');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enclose-1', 'enclose', 'Farmers began to enclose their fields with stone walls in the 1700s.', '18 世纪,农民开始用石墙把田地围起来。', 'enclose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reassure-1', 'reassure', 'The government tried to reassure the public that the food was safe.', '政府试图让公众放心,告诉他们这些食品是安全的。', 'reassure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('situate-1', 'situate', 'Planners decided to situate the new factory far from the river.', '规划者决定把新工厂建在远离河流的地方。', 'situate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('steer-1', 'steer', 'The new policy aims to steer young people towards careers in science.', '新政策旨在引导年轻人从事科学领域的职业。', 'steer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intimidate-1', 'intimidate', 'Larger males use loud calls to intimidate their rivals.', '体型较大的雄性用响亮的叫声恐吓对手。', 'intimidate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('restrain-1', 'restrain', 'Interest rates were raised to restrain the rapid growth in spending.', '提高利率是为了抑制支出的快速增长。', 'restrain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resume-1', 'resume', 'Work on the bridge will resume once the river level has fallen.', '河水水位下降后,桥梁工程将重新开始。', 'resume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forge-1', 'forge', 'The two towns forged close links through trade and marriage.', '这两个城镇通过贸易和联姻建立了密切的联系。', 'forged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forge-2', 'forge', 'The criminals had forged documents to sell the land illegally.', '这些罪犯伪造了文件,非法出售土地。', 'forged');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inflict-1', 'inflict', 'Strong winds can inflict serious damage on buildings along the coast.', '强风可能给沿海建筑造成严重破坏。', 'inflict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('betray-1', 'betray', 'A slight change in the voice can betray a person''s true feelings.', '声音的细微变化可能泄露一个人的真实情感。', 'betray');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endeavour-1', 'endeavour', 'Scientific endeavour depends on the free exchange of ideas between researchers.', '科学上的努力有赖于研究者之间自由交流思想。', 'endeavour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excel-1', 'excel', 'Some children excel at mathematics but struggle to read.', '有些孩子擅长数学,却在阅读上很吃力。', 'excel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dwell-1', 'dwell', 'Around a thousand people dwell in caves cut into the soft rock.', '大约有一千人居住在软岩中开凿的洞穴里。', 'dwell');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mobilise-1', 'mobilise', 'The government mobilised thousands of volunteers to help after the flood.', '洪水过后,政府动员了数千名志愿者提供帮助。', 'mobilised');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspend-1', 'suspend', 'The trial of the drug was suspended after several patients became ill.', '几名患者生病后,这种药物的试验被暂停。', 'suspended');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reverse-1', 'reverse', 'Scientists doubt whether the damage to the reef can be reversed.', '科学家怀疑珊瑚礁受到的损害能否逆转。', 'reversed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reverse-2', 'reverse', 'The second study produced exactly the reverse result.', '第二项研究得出了完全相反的结果。', 'reverse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vanish-1', 'vanish', 'Many species of frog could vanish completely within the next few decades.', '许多种类的青蛙可能在未来几十年内完全消失。', 'vanish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fade-1', 'fade', 'Colours in old paintings gradually fade when they are exposed to light.', '古画的颜色在光照下会逐渐褪去。', 'fade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shrink-1', 'shrink', 'The size of the glacier has continued to shrink in recent decades.', '近几十年来,这条冰川的面积持续缩小。', 'shrink');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('split-1', 'split', 'The company split into two separate businesses in the early 1990s.', '这家公司在 20 世纪 90 年代初分裂成两家独立的企业。', 'split');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pose-1', 'pose', 'Plastic waste poses a serious danger to sea birds and turtles.', '塑料垃圾对海鸟和海龟构成严重危险。', 'poses');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tap-1', 'tap', 'Engineers hope to tap the heat stored deep under the ground.', '工程师希望开发利用地下深处储存的热能。', 'tap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leap-1', 'leap', 'The invention of the telescope was a great leap forward for astronomy.', '望远镜的发明是天文学的一次巨大飞跃。', 'leap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rescue-1', 'rescue', 'Volunteers worked through the night to rescue birds caught in the oil.', '志愿者彻夜营救被石油困住的鸟类。', 'rescue');
